window.CODIGO_JAVA["contabilidad-ms"] = {"src/main/java/com/mx/josesaid/develop/contabilidad/ContabilidadApplication.java": "package com.mx.josesaid.develop.contabilidad;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.boot.context.properties.ConfigurationPropertiesScan;\nimport org.springframework.scheduling.annotation.EnableScheduling;\n\n/** Punto de entrada de contabilidad-ms. */\n@SpringBootApplication\n@EnableScheduling\n@ConfigurationPropertiesScan\npublic class ContabilidadApplication {\n\n    /** Arranca la aplicación Spring Boot. */\n    public static void main(String[] args) {\n        SpringApplication.run(ContabilidadApplication.class, args);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/api/ContabilidadControlador.java": "package com.mx.josesaid.develop.contabilidad.api;\n\nimport com.mx.josesaid.develop.contabilidad.application.ContabilidadService;\nimport com.mx.josesaid.develop.contabilidad.domain.Balanza;\nimport com.mx.josesaid.develop.contabilidad.domain.CuentaContable;\nimport com.mx.josesaid.develop.contabilidad.domain.EstatusPeriodo;\nimport com.mx.josesaid.develop.contabilidad.domain.EstatusPoliza;\nimport com.mx.josesaid.develop.contabilidad.domain.Movimiento;\nimport com.mx.josesaid.develop.contabilidad.domain.Naturaleza;\nimport com.mx.josesaid.develop.contabilidad.domain.Periodo;\nimport com.mx.josesaid.develop.contabilidad.domain.Poliza;\nimport com.mx.josesaid.develop.contabilidad.domain.TipoPoliza;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.DecimalMin;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.Size;\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.ResponseStatus;\nimport org.springframework.web.bind.annotation.RestController;\nimport com.mx.josesaid.develop.contabilidad.infrastructure.idempotencia.Idempotencia;\nimport org.springframework.web.bind.annotation.RequestHeader;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.validation.annotation.Validated;\n\n/** Endpoints de contabilidad. CONTADOR escribe; DIRECCION solo consulta estados financieros y pólizas. */\n@Validated\n@RestController\n@RequestMapping(\"/v1\")\npublic class ContabilidadControlador {\n\n    private final ContabilidadService servicio;\n    private final Idempotencia idempotencia;\n\n    /** Recibe el servicio de contabilidad y el control de idempotencia. */\n    public ContabilidadControlador(ContabilidadService servicio, Idempotencia idempotencia) {\n        this.servicio = servicio;\n        this.idempotencia = idempotencia;\n    }\n\n    /** Da de alta una cuenta contable con código, nombre y naturaleza. */\n    @PostMapping(\"/cuentas\")\n    @ResponseStatus(HttpStatus.CREATED)\n    @PreAuthorize(\"hasRole('CONTADOR')\")\n    public CuentaRespuesta crearCuenta(@Valid @RequestBody CrearCuentaSolicitud solicitud) {\n        return CuentaRespuesta.de(servicio.crearCuenta(solicitud.codigo(), solicitud.nombre(), solicitud.naturaleza()));\n    }\n\n    /** Catálogo de cuentas activas. Solo lectura: lo usa Nexus para sugerir pólizas. */\n    @GetMapping(\"/cuentas\")\n    @PreAuthorize(\"hasAnyRole('CONTADOR','DIRECCION')\")\n    public List<CuentaRespuesta> listarCuentas() {\n        return servicio.listarCuentasActivas().stream().map(CuentaRespuesta::de).toList();\n    }\n\n    /** Registra una póliza. Primero valida que cuadre; luego que las cuentas estén activas y que el periodo esté abierto. Acepta Idempotency-Key. */\n    @PostMapping(\"/polizas\")\n    @PreAuthorize(\"hasRole('CONTADOR')\")\n    public ResponseEntity<?> registrarPoliza(@RequestHeader(value = Idempotencia.CABECERA, required = false) String clave,\n                                             @Valid @RequestBody RegistrarPolizaSolicitud solicitud) {\n        return idempotencia.ejecutar(clave, \"POST /v1/polizas\", solicitud, HttpStatus.CREATED, () -> {\n            List<Movimiento> movimientos = solicitud.movimientos().stream()\n                    .map(m -> new Movimiento(m.cuentaId(), m.cargo(), m.abono()))\n                    .toList();\n            return PolizaRespuesta.de(servicio.registrarPoliza(solicitud.tipo(), solicitud.fecha(), movimientos));\n        });\n    }\n\n    /** Reversa una póliza aplicada. La original queda reversada y la reversa se registra con la fecha de hoy. Nada se borra. */\n    @PostMapping(\"/polizas/{id}/reversa\")\n    @ResponseStatus(HttpStatus.CREATED)\n    @PreAuthorize(\"hasRole('CONTADOR')\")\n    public PolizaRespuesta reversarPoliza(@PathVariable UUID id) {\n        return PolizaRespuesta.de(servicio.reversarPoliza(id));\n    }\n\n    /** Lista las pólizas de un periodo con formato AAAA-MM. */\n    @GetMapping(\"/polizas\")\n    @PreAuthorize(\"hasAnyRole('CONTADOR','DIRECCION')\")\n    public List<PolizaRespuesta> listarPolizas(@RequestParam @Size(max = 20) String periodo) {\n        return servicio.listarPolizas(YearMonth.parse(periodo)).stream().map(PolizaRespuesta::de).toList();\n    }\n\n    /** Devuelve una póliza con sus movimientos. */\n    @GetMapping(\"/polizas/{id}\")\n    @PreAuthorize(\"hasAnyRole('CONTADOR','DIRECCION')\")\n    public PolizaRespuesta obtenerPoliza(@PathVariable UUID id) {\n        return PolizaRespuesta.de(servicio.obtenerPoliza(id));\n    }\n\n    /** Cierra un periodo contable. Después no admite pólizas ni reversas. */\n    @PostMapping(\"/periodos/{anioMes}/cierre\")\n    @PreAuthorize(\"hasRole('CONTADOR')\")\n    public PeriodoRespuesta cerrarPeriodo(@PathVariable String anioMes) {\n        return PeriodoRespuesta.de(servicio.cerrarPeriodo(YearMonth.parse(anioMes)));\n    }\n\n    /** Devuelve la balanza de comprobación del periodo indicado. */\n    @GetMapping(\"/estados-financieros\")\n    @PreAuthorize(\"hasAnyRole('CONTADOR','DIRECCION')\")\n    public Balanza estadosFinancieros(@RequestParam @Size(max = 20) String periodo) {\n        return servicio.estadosFinancieros(YearMonth.parse(periodo));\n    }\n\n    /**\n     * Datos para dar de alta una cuenta contable.\n     *\n     * @param codigo componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     * @param naturaleza componente de tipo {@code Naturaleza}.\n     */\n    public record CrearCuentaSolicitud(\n            @NotBlank @Size(max = 20) String codigo,\n            @NotBlank @Size(max = 150) String nombre,\n            @NotNull Naturaleza naturaleza) {\n    }\n\n    /**\n     * Movimiento de una póliza: cuenta, cargo y abono.\n     *\n     * @param cuentaId componente de tipo {@code UUID}.\n     * @param cargo componente de tipo {@code BigDecimal}.\n     * @param abono componente de tipo {@code BigDecimal}.\n     */\n    public record MovimientoSolicitud(\n            @NotNull UUID cuentaId,\n            @DecimalMin(\"0\") BigDecimal cargo,\n            @DecimalMin(\"0\") BigDecimal abono) {\n    }\n\n    /**\n     * Datos para registrar una póliza: tipo, fecha y movimientos.\n     *\n     * @param tipo componente de tipo {@code TipoPoliza}.\n     * @param fecha componente de tipo {@code LocalDate}.\n     * @param movimientos componente de tipo {@code List<MovimientoSolicitud>}.\n     */\n    public record RegistrarPolizaSolicitud(\n            @NotNull TipoPoliza tipo,\n            @NotNull LocalDate fecha,\n            @NotNull @Size(min = 2) List<@Valid MovimientoSolicitud> movimientos) {\n    }\n\n    /**\n     * Respuesta de una cuenta contable.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param codigo componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     * @param naturaleza componente de tipo {@code Naturaleza}.\n     * @param activa componente de tipo {@code boolean}.\n     */\n    public record CuentaRespuesta(UUID id, String codigo, String nombre, Naturaleza naturaleza, boolean activa) {\n        /** Convierte una cuenta en su respuesta. */\n        static CuentaRespuesta de(CuentaContable c) {\n            return new CuentaRespuesta(c.getId(), c.getCodigo(), c.getNombre(), c.getNaturaleza(), c.isActiva());\n        }\n    }\n\n    /**\n     * Movimiento de una póliza en la respuesta.\n     *\n     * @param cuentaId componente de tipo {@code UUID}.\n     * @param cargo componente de tipo {@code BigDecimal}.\n     * @param abono componente de tipo {@code BigDecimal}.\n     */\n    public record MovimientoRespuesta(UUID cuentaId, BigDecimal cargo, BigDecimal abono) {\n    }\n\n    /**\n     * Respuesta de una póliza.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param periodo componente de tipo {@code String}.\n     * @param tipo componente de tipo {@code TipoPoliza}.\n     * @param fecha componente de tipo {@code LocalDate}.\n     * @param estatus componente de tipo {@code EstatusPoliza}.\n     * @param reversaDe componente de tipo {@code UUID}.\n     * @param total componente de tipo {@code BigDecimal}.\n     * @param movimientos componente de tipo {@code List<MovimientoRespuesta>}.\n     */\n    public record PolizaRespuesta(UUID id, String periodo, TipoPoliza tipo, LocalDate fecha, EstatusPoliza estatus,\n                                  UUID reversaDe, BigDecimal total, List<MovimientoRespuesta> movimientos) {\n        /** Convierte una póliza en su respuesta. */\n        static PolizaRespuesta de(Poliza p) {\n            return new PolizaRespuesta(p.getId(), p.getPeriodo().toString(), p.getTipo(), p.getFecha(),\n                    p.getEstatus(), p.getReversaDe(), p.total(),\n                    p.getMovimientos().stream()\n                            .map(m -> new MovimientoRespuesta(m.getCuentaId(), m.getCargo(), m.getAbono()))\n                            .toList());\n        }\n    }\n\n    /**\n     * Estatus de un periodo contable.\n     *\n     * @param anioMes componente de tipo {@code String}.\n     * @param estatus componente de tipo {@code EstatusPeriodo}.\n     */\n    public record PeriodoRespuesta(String anioMes, EstatusPeriodo estatus) {\n        /** Convierte un periodo en su respuesta. */\n        static PeriodoRespuesta de(Periodo p) {\n            return new PeriodoRespuesta(p.getAnioMes().toString(), p.getEstatus());\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/api/ManejadorErrores.java": "package com.mx.josesaid.develop.contabilidad.api;\n\nimport com.mx.josesaid.develop.contabilidad.domain.ConflictoException;\nimport com.mx.josesaid.develop.contabilidad.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.contabilidad.domain.ReglaDeNegocioException;\nimport java.net.URI;\nimport java.time.format.DateTimeParseException;\nimport java.util.stream.Collectors;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ProblemDetail;\nimport org.springframework.orm.ObjectOptimisticLockingFailureException;\nimport org.springframework.web.bind.MethodArgumentNotValidException;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\n\n/** Errores RFC 9457 con type estable {@code urn:josesaid:contabilidad:error:<slug>}. */\n@RestControllerAdvice\npublic class ManejadorErrores {\n\n    private static final String PREFIJO = \"urn:josesaid:contabilidad:error:\";\n\n    /** Convierte un recurso inexistente en un problema HTTP. */\n    @ExceptionHandler(RecursoNoEncontradoException.class)\n    ProblemDetail noEncontrado(RecursoNoEncontradoException ex) {\n        return problema(HttpStatus.NOT_FOUND, \"no-encontrado\", ex.getMessage());\n    }\n\n    /** Convierte un conflicto de estado, por ejemplo un periodo cerrado, en un problema HTTP. */\n    @ExceptionHandler(ConflictoException.class)\n    ProblemDetail conflicto(ConflictoException ex) {\n        return problema(HttpStatus.CONFLICT, \"conflicto\", ex.getMessage());\n    }\n\n    /** Convierte un conflicto de concurrencia en un problema HTTP. El cliente debe reintentar. */\n    @ExceptionHandler(ObjectOptimisticLockingFailureException.class)\n    ProblemDetail concurrencia(ObjectOptimisticLockingFailureException ex) {\n        return problema(HttpStatus.CONFLICT, \"conflicto-concurrencia\",\n                \"El registro cambió mientras se procesaba. Vuelva a intentarlo.\");\n    }\n\n    /** Convierte una regla de negocio incumplida, por ejemplo una póliza que no cuadra, en un problema HTTP. */\n    @ExceptionHandler(ReglaDeNegocioException.class)\n    ProblemDetail reglaDeNegocio(ReglaDeNegocioException ex) {\n        return problema(HttpStatus.UNPROCESSABLE_ENTITY, \"regla-de-negocio\", ex.getMessage());\n    }\n\n    /** Convierte errores de validación en un problema HTTP con el detalle de cada campo. */\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    ProblemDetail validacion(MethodArgumentNotValidException ex) {\n        String detalle = ex.getBindingResult().getFieldErrors().stream()\n                .map(e -> e.getField() + \": \" + e.getDefaultMessage())\n                .collect(Collectors.joining(\"; \"));\n        return problema(HttpStatus.BAD_REQUEST, \"datos-invalidos\", detalle);\n    }\n\n    /** Convierte una fecha con formato incorrecto en un problema HTTP. */\n    @ExceptionHandler(DateTimeParseException.class)\n    ProblemDetail fechaInvalida(DateTimeParseException ex) {\n        return problema(HttpStatus.BAD_REQUEST, \"datos-invalidos\", \"Formato de periodo inválido. Use AAAA-MM\");\n    }\n\n    /** Construye la respuesta de error con su estatus, código y detalle. */\n    private static ProblemDetail problema(HttpStatus estatus, String slug, String detalle) {\n        ProblemDetail pd = ProblemDetail.forStatusAndDetail(estatus, detalle);\n        pd.setType(URI.create(PREFIJO + slug));\n        pd.setTitle(estatus.getReasonPhrase());\n        return pd;\n    }\n\n    /** Convierte parámetros inválidos en un problema HTTP. */\n    @org.springframework.web.bind.annotation.ExceptionHandler(jakarta.validation.ConstraintViolationException.class)\n    org.springframework.http.ProblemDetail parametrosInvalidos(jakarta.validation.ConstraintViolationException e) {\n        return org.springframework.http.ProblemDetail.forStatusAndDetail(\n                org.springframework.http.HttpStatus.BAD_REQUEST, \"Revise los parámetros indicados\");\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/application/ContabilidadService.java": "package com.mx.josesaid.develop.contabilidad.application;\n\nimport com.mx.josesaid.develop.contabilidad.domain.Balanza;\nimport com.mx.josesaid.develop.contabilidad.domain.ConflictoException;\nimport com.mx.josesaid.develop.contabilidad.domain.CuentaContable;\nimport com.mx.josesaid.develop.contabilidad.domain.CuentaRepositorio;\nimport com.mx.josesaid.develop.contabilidad.domain.Movimiento;\nimport com.mx.josesaid.develop.contabilidad.domain.Naturaleza;\nimport com.mx.josesaid.develop.contabilidad.domain.Periodo;\nimport com.mx.josesaid.develop.contabilidad.domain.PeriodoRepositorio;\nimport com.mx.josesaid.develop.contabilidad.domain.Poliza;\nimport com.mx.josesaid.develop.contabilidad.domain.PolizaRepositorio;\nimport com.mx.josesaid.develop.contabilidad.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.contabilidad.domain.ReglaDeNegocioException;\nimport com.mx.josesaid.develop.contabilidad.domain.TipoPoliza;\nimport java.time.Clock;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Casos de uso de contabilidad. Los eventos se guardan en el outbox en la misma transacción. */\n@Service\npublic class ContabilidadService {\n\n    public static final String EVENTO_POLIZA_APLICADA = \"poliza-aplicada\";\n    public static final String EVENTO_PERIODO_CERRADO = \"periodo-cerrado\";\n\n    private final CuentaRepositorio cuentas;\n    private final PeriodoRepositorio periodos;\n    private final PolizaRepositorio polizas;\n    private final PublicadorEventos eventos;\n    private final Clock reloj;\n\n    /** Recibe los repositorios de cuentas, periodos y pólizas, el publicador de eventos y el reloj. */\n    public ContabilidadService(CuentaRepositorio cuentas, PeriodoRepositorio periodos, PolizaRepositorio polizas,\n                               PublicadorEventos eventos, Clock reloj) {\n        this.cuentas = cuentas;\n        this.periodos = periodos;\n        this.polizas = polizas;\n        this.eventos = eventos;\n        this.reloj = reloj;\n    }\n\n    /** Crea una cuenta contable activa. */\n    @Transactional\n    public CuentaContable crearCuenta(String codigo, String nombre, Naturaleza naturaleza) {\n        if (codigo != null && cuentas.existePorCodigo(codigo.trim())) {\n            throw new ConflictoException(\"Ya existe la cuenta \" + codigo.trim());\n        }\n        return cuentas.guardar(CuentaContable.crear(codigo, nombre, naturaleza));\n    }\n\n    /** Lista las cuentas activas. */\n    @Transactional(readOnly = true)\n    public List<CuentaContable> listarCuentasActivas() {\n        return cuentas.listarActivas();\n    }\n\n    /** Registra una póliza. Primero valida el cuadre (422), luego que el periodo esté abierto (409). */\n    @Transactional\n    public Poliza registrarPoliza(TipoPoliza tipo, LocalDate fecha, List<Movimiento> movimientos) {\n        Poliza poliza = Poliza.aplicar(tipo, fecha, movimientos);\n        validarCuentas(movimientos);\n        periodoAbierto(poliza.getPeriodo());\n        Poliza guardada = polizas.guardar(poliza);\n        eventos.publicar(new EventoDominio(EVENTO_POLIZA_APLICADA, guardada.getId().toString(), Map.of(\n                \"id\", guardada.getId().toString(),\n                \"periodo\", guardada.getPeriodo().toString(),\n                \"total\", guardada.total().toPlainString())));\n        return guardada;\n    }\n\n    /** Reversa una póliza aplicada con fecha de hoy. Las pólizas no se borran ni se editan. */\n    @Transactional\n    public Poliza reversarPoliza(UUID id) {\n        Poliza original = obtenerPoliza(id);\n        LocalDate hoy = LocalDate.now(reloj);\n        periodoAbierto(YearMonth.from(hoy));\n        Poliza reversa = original.reversar(hoy);\n        polizas.guardar(original);\n        Poliza guardada = polizas.guardar(reversa);\n        eventos.publicar(new EventoDominio(EVENTO_POLIZA_APLICADA, guardada.getId().toString(), Map.of(\n                \"id\", guardada.getId().toString(),\n                \"periodo\", guardada.getPeriodo().toString(),\n                \"total\", guardada.total().toPlainString())));\n        return guardada;\n    }\n\n    /** Lista las pólizas de un periodo. */\n    @Transactional(readOnly = true)\n    public List<Poliza> listarPolizas(YearMonth anioMes) {\n        return polizas.buscarPorPeriodo(anioMes);\n    }\n\n    /** Devuelve una póliza por id o lanza RecursoNoEncontradoException. */\n    @Transactional(readOnly = true)\n    public Poliza obtenerPoliza(UUID id) {\n        return polizas.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Póliza no encontrada: \" + id));\n    }\n\n    /** Cierra el periodo y publica el evento de cierre. Falla si el periodo no existe. */\n    @Transactional\n    public Periodo cerrarPeriodo(YearMonth anioMes) {\n        Periodo periodo = periodos.buscarPorAnioMes(anioMes)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Periodo no encontrado: \" + anioMes));\n        periodo.cerrar();\n        Periodo guardado = periodos.guardar(periodo);\n        eventos.publicar(new EventoDominio(EVENTO_PERIODO_CERRADO, anioMes.toString(), Map.of(\n                \"anioMes\", anioMes.toString())));\n        return guardado;\n    }\n\n    /** Calcula la balanza de comprobación del periodo. Falla si el periodo no existe. */\n    @Transactional(readOnly = true)\n    public Balanza estadosFinancieros(YearMonth anioMes) {\n        periodos.buscarPorAnioMes(anioMes)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Periodo no encontrado: \" + anioMes));\n        List<Poliza> lista = polizas.buscarPorPeriodo(anioMes);\n        Map<UUID, CuentaContable> mapa = new HashMap<>();\n        for (Poliza p : lista) {\n            for (Movimiento m : p.getMovimientos()) {\n                cuentas.buscarPorId(m.getCuentaId()).ifPresent(c -> mapa.put(c.getId(), c));\n            }\n        }\n        return Balanza.calcular(anioMes, lista, mapa);\n    }\n\n    /** Devuelve el periodo abierto, o lo crea si es la primera póliza del mes. Un periodo cerrado lanza 409. */\n    private Periodo periodoAbierto(YearMonth anioMes) {\n        Periodo periodo = periodos.buscarPorAnioMes(anioMes)\n                .orElseGet(() -> periodos.guardar(Periodo.abrir(anioMes)));\n        if (periodo.estaCerrado()) {\n            throw new ConflictoException(\"El periodo \" + anioMes + \" está cerrado\");\n        }\n        return periodo;\n    }\n\n    /** Verifica que cada cuenta de la póliza exista y esté activa. */\n    private void validarCuentas(List<Movimiento> movimientos) {\n        for (UUID cuentaId : movimientos.stream().map(Movimiento::getCuentaId).distinct().toList()) {\n            CuentaContable cuenta = cuentas.buscarPorId(cuentaId)\n                    .orElseThrow(() -> new ReglaDeNegocioException(\"La cuenta no existe: \" + cuentaId));\n            if (!cuenta.isActiva()) {\n                throw new ReglaDeNegocioException(\"La cuenta está inactiva: \" + cuenta.getCodigo());\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/application/EventoDominio.java": "package com.mx.josesaid.develop.contabilidad.application;\n\nimport java.util.Map;\n\n/**\n * Evento de negocio. Se guarda en el outbox y luego se envía a Kafka.\n *\n * @param tipo componente de tipo {@code String}.\n * @param agregadoId componente de tipo {@code String}.\n * @param datos componente de tipo {@code Map<String, Object>}.\n */\npublic record EventoDominio(String tipo, String agregadoId, Map<String, Object> datos) {\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/application/PublicadorEventos.java": "package com.mx.josesaid.develop.contabilidad.application;\n\n/** Puerto de publicación de eventos. La implementación usa el patrón outbox. */\npublic interface PublicadorEventos {\n\n    void publicar(EventoDominio evento);\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/config/PropiedadesJwt.java": "package com.mx.josesaid.develop.contabilidad.config;\n\nimport java.time.Duration;\nimport org.springframework.boot.context.properties.ConfigurationProperties;\n\n/**\n * Propiedades del emisor de tokens, enlazadas desde {@code contabilidad.jwt}.\n *\n * @param jwksUri URL del JWKS de usuarios-accesos-ms con la clave pública para validar tokens\n * @param duracion vida del token de acceso\n * @param emisor   valor del claim {@code iss}\n */\n@ConfigurationProperties(prefix = \"contabilidad.jwt\")\npublic record PropiedadesJwt(String jwksUri, Duration duracion, String emisor) {\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/config/RelojConfig.java": "package com.mx.josesaid.develop.contabilidad.config;\n\nimport java.time.Clock;\nimport java.time.ZoneId;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/** Reloj en UTC. Inyectarlo permite probar las reglas de tiempo sin depender de la hora real. */\n@Configuration\npublic class RelojConfig {\n\n    /** Reloj del sistema en UTC, usado para las fechas contables. */\n    @Bean\n    Clock reloj() {\n        return Clock.system(ZoneId.of(\"America/Mexico_City\"));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/config/SeguridadConfig.java": "package com.mx.josesaid.develop.contabilidad.config;\n\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchy;\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchyImpl;\n\nimport com.mx.josesaid.develop.contabilidad.seguridad.EntradaNoAutorizada;\n\nimport com.mx.josesaid.develop.contabilidad.seguridad.RevocacionSesiones;\nimport com.mx.josesaid.develop.contabilidad.seguridad.ValidadorRevocacion;\nimport org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;\nimport org.springframework.security.oauth2.jwt.JwtValidators;\n\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.NimbusJwtDecoder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;\nimport org.springframework.security.web.SecurityFilterChain;\n\n/**\n * Seguridad del servicio: API sin estado, JWT como resource server y autorización por rol.\n *\n * <p>Solo el login y el health son públicos. Todo lo demás exige un token válido.\n */\n@Configuration\n@EnableWebSecurity\n@EnableMethodSecurity\npublic class SeguridadConfig {\n\n    /** Cadena de seguridad de la API sin estado. Exige JWT válido en todo, excepto salud, info y métricas. */\n    @Bean\n    SecurityFilterChain cadenaSeguridad(HttpSecurity http) throws Exception {\n        http\n            .csrf(csrf -> csrf.disable()) // API sin cookies de sesión: no aplica CSRF\n            .sessionManagement(sesion -> sesion.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/actuator/health\", \"/actuator/health/**\", \"/actuator/prometheus\").permitAll()\n                .anyRequest().authenticated())\n            .oauth2ResourceServer(oauth -> oauth.authenticationEntryPoint(new EntradaNoAutorizada()).jwt(jwt -> jwt.jwtAuthenticationConverter(convertidorJwt())));\n        return http.build();\n    }\n\n    /** Convierte el claim {@code roles} en autoridades {@code ROLE_*}. */\n    @Bean\n    JwtAuthenticationConverter convertidorJwt() {\n        JwtGrantedAuthoritiesConverter autoridades = new JwtGrantedAuthoritiesConverter();\n        autoridades.setAuthoritiesClaimName(\"roles\");\n        autoridades.setAuthorityPrefix(\"ROLE_\");\n        JwtAuthenticationConverter convertidor = new JwtAuthenticationConverter();\n        convertidor.setJwtGrantedAuthoritiesConverter(autoridades);\n        return convertidor;\n    }\n\n    /** Valida la firma con la clave pública que publica usuarios-accesos-ms (JWKS). */\n    @Bean\n    JwtDecoder jwtDecoder(PropiedadesJwt propiedades, RevocacionSesiones revocaciones) {\n        var decoder = NimbusJwtDecoder.withJwkSetUri(propiedades.jwksUri()).build();\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefault(),\n                new ValidadorRevocacion(revocaciones)));\n        return decoder;\n    }\n\n    /** Codificador de contraseñas BCrypt. */\n    @Bean\n    PasswordEncoder passwordEncoder() {\n        return new BCryptPasswordEncoder();\n    }\n\n    /** ADMIN puede hacer todo: hereda todos los roles de negocio. */\n    @Bean\n    RoleHierarchy jerarquiaRoles() {\n        return RoleHierarchyImpl.withDefaultRolePrefix()\n                .role(\"ADMIN\").implies(\"FINANZAS\", \"CONTADOR\", \"VENTAS\", \"COMPRAS\", \"ALMACEN\", \"OPERACIONES\", \"CALIDAD\", \"DIRECCION\", \"LEGAL\", \"JEFE_AREA\")\n                .build();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/Balanza.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\nimport static java.math.BigDecimal.ZERO;\n\nimport java.math.BigDecimal;\nimport java.time.YearMonth;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.TreeMap;\nimport java.util.UUID;\n\n/**\n * Balanza de comprobación de un periodo. Solo incluye lo que sí está calculado:\n * balanza de comprobación. Estado de resultados y balance general son pendientes.\n  * @param periodo componente de tipo {@code String}.\n  * @param lineas componente de tipo {@code List<Linea>}.\n  * @param totalCargos componente de tipo {@code BigDecimal}.\n  * @param totalAbonos componente de tipo {@code BigDecimal}.\n  * @param cuadra componente de tipo {@code boolean}.\n */\npublic record Balanza(String periodo, List<Linea> lineas, BigDecimal totalCargos, BigDecimal totalAbonos,\n                      boolean cuadra) {\n\n    /**\n     * Línea de la balanza: cuenta, cargos, abonos y saldo según la naturaleza de la cuenta.\n     *\n     * @param cuentaId componente de tipo {@code UUID}.\n     * @param codigo componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     * @param cargos componente de tipo {@code BigDecimal}.\n     * @param abonos componente de tipo {@code BigDecimal}.\n     * @param saldo componente de tipo {@code BigDecimal}.\n     */\n    public record Linea(UUID cuentaId, String codigo, String nombre, BigDecimal cargos, BigDecimal abonos,\n                        BigDecimal saldo) {\n    }\n\n    /** Suma cargos y abonos por cuenta. El saldo sigue la naturaleza de cada cuenta. */\n    public static Balanza calcular(YearMonth periodo, List<Poliza> polizas, Map<UUID, CuentaContable> cuentas) {\n        Map<UUID, BigDecimal[]> acumulado = new TreeMap<>();\n        for (Poliza p : polizas) {\n            for (Movimiento m : p.getMovimientos()) {\n                BigDecimal[] t = acumulado.computeIfAbsent(m.getCuentaId(), k -> new BigDecimal[]{ZERO, ZERO});\n                t[0] = t[0].add(m.getCargo());\n                t[1] = t[1].add(m.getAbono());\n            }\n        }\n        List<Linea> lineas = new ArrayList<>();\n        BigDecimal totalCargos = ZERO;\n        BigDecimal totalAbonos = ZERO;\n        for (Map.Entry<UUID, BigDecimal[]> e : acumulado.entrySet()) {\n            CuentaContable c = cuentas.get(e.getKey());\n            if (c == null) {\n                throw new IllegalStateException(\"Cuenta sin datos para la balanza: \" + e.getKey());\n            }\n            BigDecimal cargos = e.getValue()[0];\n            BigDecimal abonos = e.getValue()[1];\n            BigDecimal saldo = c.getNaturaleza() == Naturaleza.DEUDORA ? cargos.subtract(abonos) : abonos.subtract(cargos);\n            lineas.add(new Linea(c.getId(), c.getCodigo(), c.getNombre(), cargos, abonos, saldo));\n            totalCargos = totalCargos.add(cargos);\n            totalAbonos = totalAbonos.add(abonos);\n        }\n        return new Balanza(periodo.toString(), lineas, totalCargos, totalAbonos,\n                totalCargos.compareTo(totalAbonos) == 0);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/ConflictoException.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\n/** Conflicto con el estado actual. HTTP 409. */\npublic class ConflictoException extends RuntimeException {\n    /** Se lanza cuando la operación choca con el estado actual. Se responde como conflicto. */\n    public ConflictoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/CuentaContable.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\nimport java.util.UUID;\n\n/** Cuenta del catálogo. No se elimina: se desactiva. Las cuentas con movimientos conservan su historial. */\npublic class CuentaContable {\n\n    private final UUID id;\n    private final String codigo;\n    private final String nombre;\n    private final Naturaleza naturaleza;\n    private boolean activa;\n\n    /** Constructor privado: las cuentas se crean con sus fábricas. */\n    private CuentaContable(UUID id, String codigo, String nombre, Naturaleza naturaleza, boolean activa) {\n        this.id = id;\n        this.codigo = codigo;\n        this.nombre = nombre;\n        this.naturaleza = naturaleza;\n        this.activa = activa;\n    }\n\n    /** Crea una cuenta activa con código, nombre y naturaleza. */\n    public static CuentaContable crear(String codigo, String nombre, Naturaleza naturaleza) {\n        if (codigo == null || codigo.isBlank() || codigo.length() > 20) {\n            throw new ReglaDeNegocioException(\"El código de cuenta es obligatorio (máximo 20 caracteres)\");\n        }\n        if (nombre == null || nombre.isBlank()) {\n            throw new ReglaDeNegocioException(\"El nombre de la cuenta es obligatorio\");\n        }\n        if (naturaleza == null) {\n            throw new ReglaDeNegocioException(\"La naturaleza de la cuenta es obligatoria\");\n        }\n        return new CuentaContable(UUID.randomUUID(), codigo.trim(), nombre.trim(), naturaleza, true);\n    }\n\n    /** Reconstruye una cuenta desde la base de datos sin aplicar reglas. */\n    public static CuentaContable reconstruir(UUID id, String codigo, String nombre, Naturaleza naturaleza, boolean activa) {\n        return new CuentaContable(id, codigo, nombre, naturaleza, activa);\n    }\n\n    /** Desactiva la cuenta. Una cuenta inactiva no admite pólizas nuevas. */\n    public void desactivar() {\n        this.activa = false;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el código de la cuenta. */\n    public String getCodigo() { return codigo; }\n    /** Devuelve el nombre. */\n    public String getNombre() { return nombre; }\n    /** Devuelve la naturaleza: deudora o acreedora. */\n    public Naturaleza getNaturaleza() { return naturaleza; }\n    /** Indica si la cuenta está activa. */\n    public boolean isActiva() { return activa; }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/CuentaRepositorio.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar cuentas contables, sin depender de JPA. */\npublic interface CuentaRepositorio {\n    CuentaContable guardar(CuentaContable cuenta);\n    Optional<CuentaContable> buscarPorId(UUID id);\n    boolean existePorCodigo(String codigo);\n    /** Cuentas activas, ordenadas por código. */\n    List<CuentaContable> listarActivas();\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/EstatusPeriodo.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\n/** Estatus del periodo: abierto o cerrado. */\npublic enum EstatusPeriodo { ABIERTO, CERRADO }\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/EstatusPoliza.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\n/** APLICADA es el estado al registrar. REVERSADA marca la póliza original cuando se compensa. BORRADOR queda reservado para captura diferida (pendiente). */\npublic enum EstatusPoliza { BORRADOR, APLICADA, REVERSADA }\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/Movimiento.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\nimport static java.math.BigDecimal.ZERO;\nimport static java.math.RoundingMode.HALF_EVEN;\n\n/** Un renglón de póliza: exactamente un cargo o un abono, ambos positivos o cero. */\npublic final class Movimiento {\n\n    private final UUID cuentaId;\n    private final BigDecimal cargo;\n    private final BigDecimal abono;\n\n    /** Crea un movimiento de póliza con su cuenta, cargo y abono. */\n    public Movimiento(UUID cuentaId, BigDecimal cargo, BigDecimal abono) {\n        if (cuentaId == null) {\n            throw new ReglaDeNegocioException(\"Cada movimiento requiere una cuenta\");\n        }\n        BigDecimal c = (cargo == null ? ZERO : cargo).setScale(2, HALF_EVEN);\n        BigDecimal a = (abono == null ? ZERO : abono).setScale(2, HALF_EVEN);\n        if (c.signum() < 0 || a.signum() < 0) {\n            throw new ReglaDeNegocioException(\"Cargos y abonos no pueden ser negativos\");\n        }\n        boolean soloCargo = c.signum() > 0 && a.signum() == 0;\n        boolean soloAbono = a.signum() > 0 && c.signum() == 0;\n        if (!soloCargo && !soloAbono) {\n            throw new ReglaDeNegocioException(\"Cada movimiento debe tener un cargo o un abono, no ambos ni ninguno\");\n        }\n        this.cuentaId = cuentaId;\n        this.cargo = c;\n        this.abono = a;\n    }\n\n    /** Contrapartida para reversar una póliza: el cargo pasa a abono y viceversa. */\n    public Movimiento invertir() {\n        return new Movimiento(cuentaId, abono, cargo);\n    }\n\n    /** Devuelve el id de la cuenta. */\n    public UUID getCuentaId() { return cuentaId; }\n    /** Devuelve el cargo. */\n    public BigDecimal getCargo() { return cargo; }\n    /** Devuelve el abono. */\n    public BigDecimal getAbono() { return abono; }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/Naturaleza.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\n/** Naturaleza de la cuenta: determina si su saldo crece con cargos o con abonos. */\npublic enum Naturaleza { DEUDORA, ACREEDORA }\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/Periodo.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\nimport java.time.YearMonth;\n\n/** Periodo contable mensual. Un periodo cerrado no admite pólizas nuevas ni reversas. */\npublic class Periodo {\n\n    private final YearMonth anioMes;\n    private EstatusPeriodo estatus;\n\n    /** Constructor privado: los periodos se crean con sus fábricas. */\n    private Periodo(YearMonth anioMes, EstatusPeriodo estatus) {\n        this.anioMes = anioMes;\n        this.estatus = estatus;\n    }\n\n    /** Abre un periodo nuevo en estatus abierto. */\n    public static Periodo abrir(YearMonth anioMes) {\n        return new Periodo(anioMes, EstatusPeriodo.ABIERTO);\n    }\n\n    /** Reconstruye un periodo desde la base de datos. */\n    public static Periodo reconstruir(YearMonth anioMes, EstatusPeriodo estatus) {\n        return new Periodo(anioMes, estatus);\n    }\n\n    /** Cierra el periodo. Un periodo ya cerrado no se vuelve a cerrar. */\n    public void cerrar() {\n        if (estatus == EstatusPeriodo.CERRADO) {\n            throw new ConflictoException(\"El periodo \" + anioMes + \" ya está cerrado\");\n        }\n        this.estatus = EstatusPeriodo.CERRADO;\n    }\n\n    /** Indica si el periodo está cerrado. */\n    public boolean estaCerrado() {\n        return estatus == EstatusPeriodo.CERRADO;\n    }\n\n    /** Devuelve el año y mes del periodo. */\n    public YearMonth getAnioMes() { return anioMes; }\n    /** Devuelve el estatus del periodo. */\n    public EstatusPeriodo getEstatus() { return estatus; }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/PeriodoRepositorio.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\nimport java.time.YearMonth;\nimport java.util.Optional;\n\n/** Puerto para guardar y consultar periodos, sin depender de JPA. */\npublic interface PeriodoRepositorio {\n    Periodo guardar(Periodo periodo);\n    Optional<Periodo> buscarPorAnioMes(YearMonth anioMes);\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/Poliza.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.UUID;\n\nimport static java.math.BigDecimal.ZERO;\n\n/** Póliza contable (asiento). Debe cuadrar: suma de cargos igual a suma de abonos. */\npublic class Poliza {\n\n    private final UUID id;\n    private final YearMonth periodo;\n    private final TipoPoliza tipo;\n    private final LocalDate fecha;\n    private EstatusPoliza estatus;\n    private final UUID reversaDe;\n    private final List<Movimiento> movimientos;\n\n    /** Constructor privado: las pólizas se crean con sus fábricas. */\n    private Poliza(UUID id, YearMonth periodo, TipoPoliza tipo, LocalDate fecha, EstatusPoliza estatus,\n                   UUID reversaDe, List<Movimiento> movimientos) {\n        this.id = id;\n        this.periodo = periodo;\n        this.tipo = tipo;\n        this.fecha = fecha;\n        this.estatus = estatus;\n        this.reversaDe = reversaDe;\n        this.movimientos = new ArrayList<>(movimientos);\n    }\n\n    /** Valida el cuadre y crea la póliza aplicada. */\n    public static Poliza aplicar(TipoPoliza tipo, LocalDate fecha, List<Movimiento> movimientos) {\n        if (tipo == null) {\n            throw new ReglaDeNegocioException(\"El tipo de póliza es obligatorio\");\n        }\n        if (fecha == null) {\n            throw new ReglaDeNegocioException(\"La fecha de la póliza es obligatoria\");\n        }\n        if (movimientos == null || movimientos.size() < 2) {\n            throw new ReglaDeNegocioException(\"La póliza requiere al menos dos movimientos\");\n        }\n        BigDecimal cargos = movimientos.stream().map(Movimiento::getCargo).reduce(ZERO, BigDecimal::add);\n        BigDecimal abonos = movimientos.stream().map(Movimiento::getAbono).reduce(ZERO, BigDecimal::add);\n        if (cargos.compareTo(abonos) != 0) {\n            throw new ReglaDeNegocioException(\"La póliza no cuadra: cargos \" + cargos.toPlainString()\n                    + \" y abonos \" + abonos.toPlainString());\n        }\n        return new Poliza(UUID.randomUUID(), YearMonth.from(fecha), tipo, fecha, EstatusPoliza.APLICADA, null,\n                movimientos);\n    }\n\n    /** Crea la póliza de reversa con los movimientos invertidos y marca esta póliza como REVERSADA. */\n    public Poliza reversar(LocalDate fechaReversa) {\n        if (estatus != EstatusPoliza.APLICADA) {\n            throw new ConflictoException(\"Solo una póliza aplicada puede reversarse\");\n        }\n        if (fechaReversa == null) {\n            throw new ReglaDeNegocioException(\"La fecha de la reversa es obligatoria\");\n        }\n        this.estatus = EstatusPoliza.REVERSADA;\n        List<Movimiento> invertidos = movimientos.stream().map(Movimiento::invertir).toList();\n        return new Poliza(UUID.randomUUID(), YearMonth.from(fechaReversa), tipo, fechaReversa,\n                EstatusPoliza.APLICADA, id, invertidos);\n    }\n\n    /** Reconstruye desde la persistencia sin volver a validar. */\n    public static Poliza reconstruir(UUID id, YearMonth periodo, TipoPoliza tipo, LocalDate fecha,\n                                     EstatusPoliza estatus, UUID reversaDe, List<Movimiento> movimientos) {\n        return new Poliza(id, periodo, tipo, fecha, estatus, reversaDe, movimientos);\n    }\n\n    /** Devuelve el total de la póliza: la suma de sus cargos. */\n    public BigDecimal total() {\n        return movimientos.stream().map(Movimiento::getCargo).reduce(ZERO, BigDecimal::add);\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el periodo de la póliza. */\n    public YearMonth getPeriodo() { return periodo; }\n    /** Devuelve el tipo de póliza. */\n    public TipoPoliza getTipo() { return tipo; }\n    /** Devuelve la fecha de la póliza. */\n    public LocalDate getFecha() { return fecha; }\n    /** Devuelve el estatus: aplicada o reversada. */\n    public EstatusPoliza getEstatus() { return estatus; }\n    /** Devuelve el id de la póliza que esta reversa anula, o nulo. */\n    public UUID getReversaDe() { return reversaDe; }\n    /** Devuelve los movimientos, en una vista de solo lectura. */\n    public List<Movimiento> getMovimientos() { return Collections.unmodifiableList(movimientos); }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/PolizaRepositorio.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\nimport java.time.YearMonth;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar pólizas, sin depender de JPA. */\npublic interface PolizaRepositorio {\n    Poliza guardar(Poliza poliza);\n    Optional<Poliza> buscarPorId(UUID id);\n    List<Poliza> buscarPorPeriodo(YearMonth anioMes);\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/RecursoNoEncontradoException.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\n/** El recurso no existe. HTTP 404. */\npublic class RecursoNoEncontradoException extends RuntimeException {\n    /** Se lanza cuando no existe el recurso pedido. */\n    public RecursoNoEncontradoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/ReglaDeNegocioException.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\n/** Una operación viola una regla de negocio. HTTP 422. */\npublic class ReglaDeNegocioException extends RuntimeException {\n    /** Se lanza cuando una regla de negocio no se cumple. El mensaje se muestra al cliente. */\n    public ReglaDeNegocioException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/domain/TipoPoliza.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\n/** Tipo de póliza: ingreso, egreso o diario. */\npublic enum TipoPoliza { INGRESO, EGRESO, DIARIO }\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/idempotencia/Idempotencia.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.idempotencia;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.contabilidad.domain.ConflictoException;\nimport com.mx.josesaid.develop.contabilidad.domain.ReglaDeNegocioException;\nimport java.nio.charset.StandardCharsets;\nimport java.security.MessageDigest;\nimport java.security.NoSuchAlgorithmException;\nimport java.util.HexFormat;\nimport java.util.function.Supplier;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.stereotype.Component;\n\n/**\n * Hace seguras de reintentar las altas que reciben la cabecera Idempotency-Key.\n * Misma clave y misma petición: devuelve la respuesta original, sin crear nada nuevo.\n * Misma clave con otra petición: 422. Clave todavía en proceso: 409.\n * Sin cabecera: la operación se ejecuta como siempre.\n */\n@Component\npublic class Idempotencia {\n\n    public static final String CABECERA = \"Idempotency-Key\";\n\n    private final RegistroIdempotencia registro;\n    private final ObjectMapper mapper;\n\n    /** Recibe el registro de claves y el serializador JSON. */\n    public Idempotencia(RegistroIdempotencia registro, ObjectMapper mapper) {\n        this.registro = registro;\n        this.mapper = mapper;\n    }\n\n    /** Ejecuta una operación una sola vez por Idempotency-Key. Una misma clave con la misma petición devuelve la respuesta guardada; con otra petición, rechaza. Si la operación falla, libera la clave para reintentar. */\n    public <T> ResponseEntity<?> ejecutar(String clave, String ruta, Object peticion,\n                                          HttpStatus estado, Supplier<T> operacion) {\n        if (clave == null || clave.isBlank()) {\n            return ResponseEntity.status(estado).body(operacion.get());\n        }\n        String huella = huella(ruta, peticion);\n        if (!registro.reservar(clave, huella)) {\n            RegistroIdempotencia.Registro previo = registro.buscar(clave)\n                    .orElseThrow(() -> new ConflictoException(\"La Idempotency-Key ya no está disponible. Intente de nuevo.\"));\n            if (!previo.huella().equals(huella)) {\n                throw new ReglaDeNegocioException(\"La Idempotency-Key ya se usó con una petición distinta.\");\n            }\n            if (!previo.completada()) {\n                throw new ConflictoException(\"La petición con esta Idempotency-Key aún se está procesando.\");\n            }\n            return ResponseEntity.status(previo.estatus())\n                    .contentType(MediaType.APPLICATION_JSON)\n                    .body(previo.cuerpo());\n        }\n        T cuerpo;\n        try {\n            cuerpo = operacion.get();\n        } catch (RuntimeException e) {\n            registro.liberar(clave);\n            throw e;\n        }\n        registro.completar(clave, estado.value(), serializar(cuerpo));\n        return ResponseEntity.status(estado).body(cuerpo);\n    }\n\n    /** Calcula la huella SHA-256 de la ruta y el cuerpo de la petición, para detectar si una clave se reutiliza con otra petición. */\n    private String huella(String ruta, Object peticion) {\n        try {\n            byte[] digest = MessageDigest.getInstance(\"SHA-256\")\n                    .digest((ruta + \"\\n\" + mapper.writeValueAsString(peticion)).getBytes(StandardCharsets.UTF_8));\n            return HexFormat.of().formatHex(digest);\n        } catch (JsonProcessingException | NoSuchAlgorithmException e) {\n            throw new IllegalStateException(\"No se pudo calcular la huella de la petición\", e);\n        }\n    }\n\n    /** Convierte la respuesta en JSON para guardarla. */\n    private String serializar(Object cuerpo) {\n        try {\n            return mapper.writeValueAsString(cuerpo);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo guardar la respuesta idempotente\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/idempotencia/RegistroIdempotencia.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.idempotencia;\n\nimport java.sql.Timestamp;\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Optional;\nimport org.springframework.dao.DuplicateKeyException;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\n\n/**\n * Guarda el estado de cada clave Idempotency-Key. Una respuesta completada se conserva 24 horas.\n * Una reserva que nunca se completó (la petición murió a medio camino) se puede retomar tras\n * {@link #CONCESION_RESERVA}, para que la clave no quede bloqueada todo el día.\n */\n@Repository\nclass RegistroIdempotencia {\n\n    static final Duration VIGENCIA = Duration.ofHours(24);\n    static final Duration CONCESION_RESERVA = Duration.ofMinutes(2);\n\n    /**\n     * Fila guardada para una clave: huella, estatus HTTP, cuerpo de la respuesta y si ya terminó.\n     *\n     * @param huella componente de tipo {@code String}.\n     * @param estatus componente de tipo {@code int}.\n     * @param cuerpo componente de tipo {@code String}.\n     * @param completada componente de tipo {@code boolean}.\n     */\n    record Registro(String huella, int estatus, String cuerpo, boolean completada) {}\n\n    private final JdbcTemplate jdbc;\n    private final Clock reloj;\n\n    RegistroIdempotencia(JdbcTemplate jdbc, Clock reloj) {\n        this.jdbc = jdbc;\n        this.reloj = reloj;\n    }\n\n    /** Busca el registro de una clave que sigue vigente. */\n    Optional<Registro> buscar(String clave) {\n        return jdbc.query(\n                \"SELECT huella, estatus_http, cuerpo, completada FROM idempotencia WHERE clave = ? AND creado_utc > ?\",\n                (rs, n) -> new Registro(rs.getString(1), rs.getInt(2), rs.getString(3), rs.getBoolean(4)),\n                clave, enTiempo(vencimiento())).stream().findFirst();\n    }\n\n    /**\n     * Reserva la clave. Devuelve false si otra petición la tiene en curso o ya terminó.\n     * Si la reserva existente nunca se completó y su concesión venció, la retoma.\n     */\n    boolean reservar(String clave, String huella) {\n        jdbc.update(\"DELETE FROM idempotencia WHERE creado_utc <= ?\", enTiempo(vencimiento()));\n        try {\n            jdbc.update(\"INSERT INTO idempotencia (clave, huella, estatus_http, cuerpo, completada, creado_utc) VALUES (?, ?, 0, NULL, FALSE, ?)\",\n                    clave, huella, enTiempo(reloj.instant()));\n            return true;\n        } catch (DuplicateKeyException e) {\n            return retomarReservaVencida(clave, huella);\n        }\n    }\n\n    /** Solo una petición gana la retoma: el UPDATE es condicional, así que es atómico. */\n    private boolean retomarReservaVencida(String clave, String huella) {\n        Instant ahora = reloj.instant();\n        int filas = jdbc.update(\n                \"UPDATE idempotencia SET huella = ?, creado_utc = ? WHERE clave = ? AND completada = FALSE AND creado_utc <= ?\",\n                huella, enTiempo(ahora), clave, enTiempo(ahora.minus(CONCESION_RESERVA)));\n        return filas == 1;\n    }\n\n    /** Guarda la respuesta de una operación terminada. */\n    void completar(String clave, int estatus, String cuerpo) {\n        jdbc.update(\"UPDATE idempotencia SET estatus_http = ?, cuerpo = ?, completada = TRUE WHERE clave = ?\",\n                estatus, cuerpo, clave);\n    }\n\n    /** Libera la reserva cuando la operación falló, para que el cliente pueda reintentar. */\n    void liberar(String clave) {\n        jdbc.update(\"DELETE FROM idempotencia WHERE clave = ? AND completada = FALSE\", clave);\n    }\n\n    /** Calcula el límite de vigencia de las claves. */\n    private Instant vencimiento() {\n        return reloj.instant().minus(VIGENCIA);\n    }\n\n    /** Convierte un instante a Timestamp para la base de datos. */\n    private static Timestamp enTiempo(Instant instante) {\n        return Timestamp.from(instante);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/indicadores/PublicadorIndicadoresPolizas.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.indicadores;\n\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.concurrent.TimeUnit;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Publica a reportes-ejecutivos-ms el indicador \"pólizas del mes\" del área de finanzas.\n *\n * <p>Cuenta las pólizas APLICADAS del mes (AAAA-MM). Se recalculan el mes actual y el anterior en cada\n * ciclo. Es una foto del periodo, no un evento: no pasa por el outbox; si un envío falla, el siguiente\n * ciclo lo corrige.\n */\n@Component\npublic class PublicadorIndicadoresPolizas {\n\n    private static final Logger log = LoggerFactory.getLogger(PublicadorIndicadoresPolizas.class);\n\n    /** Valor del enum Area de reportes-ejecutivos-ms. */\n    public static final String AREA = \"FINANZAS_CONTABILIDAD\";\n    public static final String NOMBRE = \"polizas_mes\";\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    private static final String SQL_POLIZAS = \"\"\"\n            SELECT COUNT(*)::numeric\n            FROM polizas\n            WHERE estatus = 'APLICADA'\n              AND anio_mes = ?\n            \"\"\";\n\n    private final JdbcTemplate jdbc;\n    private final KafkaTemplate<String, String> kafka;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n    private final String topico;\n\n    /** Recibe JDBC para contar, Kafka para publicar, el serializador, el reloj y el tópico. */\n    public PublicadorIndicadoresPolizas(JdbcTemplate jdbc, KafkaTemplate<String, String> kafka,\n                                        ObjectMapper mapper, Clock reloj,\n                                        @Value(\"${indicadores.topico:indicadores-areas}\") String topico) {\n        this.jdbc = jdbc;\n        this.kafka = kafka;\n        this.mapper = mapper;\n        this.reloj = reloj;\n        this.topico = topico;\n    }\n\n    /** Publica el número de pólizas del mes actual y del anterior. */\n    @Scheduled(fixedDelayString = \"${indicadores.intervalo-ms:3600000}\",\n            initialDelayString = \"${indicadores.inicio-ms:30000}\")\n    public void publicar() {\n        YearMonth actual = YearMonth.now(reloj.withZone(ZONA));\n        publicarPeriodo(actual.minusMonths(1).toString());\n        publicarPeriodo(actual.toString());\n    }\n\n    /** Calcula y envía el indicador de un mes (\"AAAA-MM\"). Un fallo se registra y se reintenta en el siguiente ciclo. */\n    public void publicarPeriodo(String periodo) {\n        BigDecimal valor = jdbc.queryForObject(SQL_POLIZAS, BigDecimal.class, periodo);\n        String payload = mapper.writeValueAsString(\n                new IndicadorEvento(AREA, NOMBRE, periodo, valor, Instant.now(reloj)));\n        try {\n            kafka.send(topico, AREA + \"|\" + NOMBRE + \"|\" + periodo, payload).get(10, TimeUnit.SECONDS);\n            log.info(\"Indicador publicado: {} {} {}\", AREA, NOMBRE, periodo);\n        } catch (InterruptedException ie) {\n            Thread.currentThread().interrupt();\n        } catch (Exception ex) {\n            log.warn(\"No se pudo publicar el indicador {} {}: {}\", NOMBRE, periodo, ex.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Formato que espera reportes-ejecutivos-ms (ListenerIndicadores.IndicadorEvento).\n     *\n     * @param area componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     * @param periodo componente de tipo {@code String}.\n     * @param valor componente de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc componente de tipo {@code Instant}.\n     */\n    public record IndicadorEvento(String area, String nombre, String periodo, BigDecimal valor,\n                                  Instant fuenteActualizadaUtc) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/outbox/OutboxEntity.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.outbox;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Evento pendiente de publicar a Kafka. Se escribe en la misma transacción que el cambio de negocio. */\n@Entity\n@Table(name = \"outbox_eventos\")\npublic class OutboxEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, length = 100)\n    private String tipo;\n\n    @Column(name = \"agregado_id\", nullable = false, length = 100)\n    private String agregadoId;\n\n    /** Sobre JSON completo: tipo, agregadoId y datos. */\n    @Column(nullable = false, columnDefinition = \"TEXT\")\n    private String payload;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"publicado_utc\")\n    private Instant publicadoUtc;\n\n    @Column(nullable = false)\n    private int intentos;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OutboxEntity() {\n        // requerido por JPA\n    }\n\n    /** Crea un evento pendiente de publicar en el outbox. */\n    public OutboxEntity(UUID id, String tipo, String agregadoId, String payload, Instant creadoUtc) {\n        this.id = id;\n        this.tipo = tipo;\n        this.agregadoId = agregadoId;\n        this.payload = payload;\n        this.creadoUtc = creadoUtc;\n        this.intentos = 0;\n    }\n\n    /** Marca el evento como publicado en la fecha indicada. */\n    public void marcarPublicado(Instant ahora) {\n        this.publicadoUtc = ahora;\n    }\n\n    /** Suma un intento fallido de publicación. */\n    public void registrarIntentoFallido() {\n        this.intentos++;\n    }\n\n    /** Devuelve el identificador del evento. */\n    public UUID getId() { return id; }\n    /** Devuelve el tipo del evento. */\n    public String getTipo() { return tipo; }\n    /** Devuelve el id del agregado al que pertenece el evento. */\n    public String getAgregadoId() { return agregadoId; }\n    /** Devuelve el contenido JSON del evento. */\n    public String getPayload() { return payload; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n    /** Devuelve la fecha de publicación en UTC, o nula si no se ha publicado. */\n    public Instant getPublicadoUtc() { return publicadoUtc; }\n    /** Devuelve el número de intentos fallidos. */\n    public int getIntentos() { return intentos; }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/outbox/OutboxJpaRepository.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.outbox;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla del outbox con Spring Data JPA. */\npublic interface OutboxJpaRepository extends JpaRepository<OutboxEntity, UUID> {\n\n    /** Eventos pendientes, del más antiguo al más nuevo, en lotes de 100. */\n    List<OutboxEntity> findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc();\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/outbox/PublicadorEventosOutbox.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.outbox;\n\nimport com.mx.josesaid.develop.contabilidad.application.EventoDominio;\nimport com.mx.josesaid.develop.contabilidad.application.PublicadorEventos;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Implementación del patrón outbox: guarda el evento en la base de datos dentro de la\n * transacción de negocio. El envío a Kafka lo hace {@link RetransmisorOutbox}.\n */\n@Component\npublic class PublicadorEventosOutbox implements PublicadorEventos {\n\n    private final OutboxJpaRepository outbox;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el serializador JSON y el reloj. */\n    public PublicadorEventosOutbox(OutboxJpaRepository outbox, ObjectMapper mapper, Clock reloj) {\n        this.outbox = outbox;\n        this.mapper = mapper;\n        this.reloj = reloj;\n    }\n\n    /** Guarda el evento en el outbox dentro de la misma transacción que el cambio de datos. */\n    @Override\n    public void publicar(EventoDominio evento) {\n        String sobre = mapper.writeValueAsString(Map.of(\n                \"tipo\", evento.tipo(),\n                \"agregadoId\", evento.agregadoId(),\n                \"datos\", evento.datos()));\n        outbox.save(new OutboxEntity(UUID.randomUUID(), evento.tipo(), evento.agregadoId(),\n                sobre, Instant.now(reloj)));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/outbox/RetransmisorOutbox.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.outbox;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.concurrent.TimeUnit;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Envía a Kafka los eventos pendientes del outbox.\n *\n * <p>Se detiene en el primer fallo para conservar el orden de los eventos.\n * Un evento con error queda pendiente y se reintenta en el siguiente ciclo.\n */\n@Component\npublic class RetransmisorOutbox {\n\n    /** Tópico donde se publican los eventos de identidad. */\n    public static final String TOPICO = \"contabilidad.eventos\";\n\n    private final OutboxJpaRepository outbox;\n    private final KafkaTemplate<String, String> kafka;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el productor de Kafka y el reloj. */\n    public RetransmisorOutbox(OutboxJpaRepository outbox, KafkaTemplate<String, String> kafka, Clock reloj) {\n        this.outbox = outbox;\n        this.kafka = kafka;\n        this.reloj = reloj;\n    }\n\n    /** Envía a Kafka los eventos pendientes. Si el envío falla, el evento queda para el siguiente intento. */\n    @Scheduled(fixedDelayString = \"${contabilidad.outbox.intervalo-ms:5000}\")\n    @Transactional\n    public void transmitir() {\n        for (OutboxEntity evento : outbox.findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc()) {\n            try {\n                kafka.send(TOPICO, evento.getAgregadoId(), evento.getPayload()).get(10, TimeUnit.SECONDS);\n                evento.marcarPublicado(Instant.now(reloj));\n            } catch (InterruptedException ie) {\n                Thread.currentThread().interrupt();\n                return;\n            } catch (Exception ex) {\n                evento.registrarIntentoFallido();\n                return;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/persistence/CuentaEntity.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.contabilidad.domain.Naturaleza;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.util.UUID;\n\n/** Fila de la tabla de cuentas contables. */\n@Entity\n@Table(name = \"cuentas_contables\")\nclass CuentaEntity {\n\n    @Id\n    UUID id;\n\n    @Column(nullable = false, unique = true, length = 20)\n    String codigo;\n\n    @Column(nullable = false, length = 150)\n    String nombre;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 10)\n    Naturaleza naturaleza;\n\n    @Column(nullable = false)\n    boolean activa;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected CuentaEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/persistence/CuentaJpaRepository.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.persistence;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de cuentas con Spring Data JPA. */\ninterface CuentaJpaRepository extends JpaRepository<CuentaEntity, UUID> {\n    boolean existsByCodigo(String codigo);\n    List<CuentaEntity> findByActivaTrueOrderByCodigoAsc();\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/persistence/CuentaRepositorioJpa.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.contabilidad.domain.CuentaContable;\nimport com.mx.josesaid.develop.contabilidad.domain.CuentaRepositorio;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de cuentas con JPA. */\n@Component\nclass CuentaRepositorioJpa implements CuentaRepositorio {\n\n    private final CuentaJpaRepository jpa;\n\n    CuentaRepositorioJpa(CuentaJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda una cuenta y devuelve la guardada. */\n    @Override\n    public CuentaContable guardar(CuentaContable c) {\n        CuentaEntity e = new CuentaEntity();\n        e.id = c.getId();\n        e.codigo = c.getCodigo();\n        e.nombre = c.getNombre();\n        e.naturaleza = c.getNaturaleza();\n        e.activa = c.isActiva();\n        jpa.save(e);\n        return c;\n    }\n\n    /** Busca una cuenta por id. */\n    @Override\n    public Optional<CuentaContable> buscarPorId(UUID id) {\n        return jpa.findById(id).map(e -> CuentaContable.reconstruir(e.id, e.codigo, e.nombre, e.naturaleza, e.activa));\n    }\n\n    /** Indica si ya existe una cuenta con ese código. */\n    @Override\n    public boolean existePorCodigo(String codigo) {\n        return jpa.existsByCodigo(codigo);\n    }\n\n    /** Lista las cuentas activas. */\n    @Override\n    public List<CuentaContable> listarActivas() {\n        return jpa.findByActivaTrueOrderByCodigoAsc().stream()\n                .map(e -> CuentaContable.reconstruir(e.id, e.codigo, e.nombre, e.naturaleza, e.activa))\n                .toList();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/persistence/MovimientoEntity.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.persistence;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.JoinColumn;\nimport jakarta.persistence.ManyToOne;\nimport jakarta.persistence.Table;\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/** Fila de un movimiento de póliza, embebida en la póliza. */\n@Entity\n@Table(name = \"movimientos\")\nclass MovimientoEntity {\n\n    @Id\n    UUID id;\n\n    @ManyToOne(fetch = FetchType.LAZY, optional = false)\n    @JoinColumn(name = \"poliza_id\", nullable = false)\n    PolizaEntity poliza;\n\n    @Column(name = \"cuenta_id\", nullable = false)\n    UUID cuentaId;\n\n    @Column(nullable = false, precision = 14, scale = 2)\n    BigDecimal cargo;\n\n    @Column(nullable = false, precision = 14, scale = 2)\n    BigDecimal abono;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected MovimientoEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/persistence/PeriodoEntity.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.contabilidad.domain.EstatusPeriodo;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\n\n/** Fila de la tabla de periodos contables. */\n@Entity\n@Table(name = \"periodos\")\nclass PeriodoEntity {\n\n    @Id\n    @Column(name = \"anio_mes\", length = 7)\n    String anioMes;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 10)\n    EstatusPeriodo estatus;\n\n    @Version\n    Long version;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected PeriodoEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/persistence/PeriodoJpaRepository.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.persistence;\n\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de periodos con Spring Data JPA, usando el año y mes como clave. */\ninterface PeriodoJpaRepository extends JpaRepository<PeriodoEntity, String> {\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/persistence/PeriodoRepositorioJpa.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.contabilidad.domain.Periodo;\nimport com.mx.josesaid.develop.contabilidad.domain.PeriodoRepositorio;\nimport java.time.YearMonth;\nimport java.util.Optional;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de periodos con JPA. */\n@Component\nclass PeriodoRepositorioJpa implements PeriodoRepositorio {\n\n    private final PeriodoJpaRepository jpa;\n\n    PeriodoRepositorioJpa(PeriodoJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda un periodo y devuelve el guardado. */\n    @Override\n    public Periodo guardar(Periodo p) {\n        PeriodoEntity e = jpa.findById(p.getAnioMes().toString()).orElseGet(PeriodoEntity::new);\n        e.anioMes = p.getAnioMes().toString();\n        e.estatus = p.getEstatus();\n        jpa.save(e);\n        return p;\n    }\n\n    /** Busca un periodo por año y mes. */\n    @Override\n    public Optional<Periodo> buscarPorAnioMes(YearMonth anioMes) {\n        return jpa.findById(anioMes.toString())\n                .map(e -> Periodo.reconstruir(YearMonth.parse(e.anioMes), e.estatus));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/persistence/PolizaEntity.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.contabilidad.domain.EstatusPoliza;\nimport com.mx.josesaid.develop.contabilidad.domain.TipoPoliza;\nimport jakarta.persistence.CascadeType;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.OneToMany;\nimport jakarta.persistence.OrderBy;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.UUID;\n\n/** Fila de la tabla de pólizas, con sus movimientos. */\n@Entity\n@Table(name = \"polizas\")\nclass PolizaEntity {\n\n    @Id\n    UUID id;\n\n    @Column(name = \"anio_mes\", nullable = false, length = 7)\n    String anioMes;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 10)\n    TipoPoliza tipo;\n\n    @Column(nullable = false)\n    LocalDate fecha;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 12)\n    EstatusPoliza estatus;\n\n    @Column(name = \"reversa_de\")\n    UUID reversaDe;\n\n    @Version\n    Long version;\n\n    @OneToMany(mappedBy = \"poliza\", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)\n    @OrderBy(\"id ASC\")\n    List<MovimientoEntity> movimientos = new ArrayList<>();\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected PolizaEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/persistence/PolizaJpaRepository.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.persistence;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de pólizas con Spring Data JPA. */\ninterface PolizaJpaRepository extends JpaRepository<PolizaEntity, UUID> {\n    List<PolizaEntity> findByAnioMes(String anioMes);\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/infrastructure/persistence/PolizaRepositorioJpa.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.contabilidad.domain.Movimiento;\nimport com.mx.josesaid.develop.contabilidad.domain.Poliza;\nimport com.mx.josesaid.develop.contabilidad.domain.PolizaRepositorio;\nimport java.time.YearMonth;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de pólizas con JPA. */\n@Component\nclass PolizaRepositorioJpa implements PolizaRepositorio {\n\n    private final PolizaJpaRepository jpa;\n\n    PolizaRepositorioJpa(PolizaJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /**\n     * Una póliza nueva guarda también sus movimientos. Una existente solo cambia su estatus:\n     * los movimientos son inmutables.\n     */\n    @Override\n    public Poliza guardar(Poliza p) {\n        Optional<PolizaEntity> existente = jpa.findById(p.getId());\n        PolizaEntity e = existente.orElseGet(PolizaEntity::new);\n        if (existente.isEmpty()) {\n            e.id = p.getId();\n            e.anioMes = p.getPeriodo().toString();\n            e.tipo = p.getTipo();\n            e.fecha = p.getFecha();\n            e.reversaDe = p.getReversaDe();\n        }\n        e.estatus = p.getEstatus();\n        if (existente.isEmpty()) {\n            for (Movimiento m : p.getMovimientos()) {\n                MovimientoEntity me = new MovimientoEntity();\n                me.id = UUID.randomUUID();\n                me.poliza = e;\n                me.cuentaId = m.getCuentaId();\n                me.cargo = m.getCargo();\n                me.abono = m.getAbono();\n                e.movimientos.add(me);\n            }\n        }\n        jpa.save(e);\n        return p;\n    }\n\n    /** Busca una póliza por id. */\n    @Override\n    public Optional<Poliza> buscarPorId(UUID id) {\n        return jpa.findById(id).map(this::aDominio);\n    }\n\n    /** Devuelve las pólizas de un periodo. */\n    @Override\n    public List<Poliza> buscarPorPeriodo(YearMonth anioMes) {\n        return jpa.findByAnioMes(anioMes.toString()).stream().map(this::aDominio).toList();\n    }\n\n    /** Convierte la fila en la póliza del dominio. */\n    private Poliza aDominio(PolizaEntity e) {\n        List<Movimiento> movs = e.movimientos.stream()\n                .map(m -> new Movimiento(m.cuentaId, m.cargo, m.abono))\n                .toList();\n        return Poliza.reconstruir(e.id, YearMonth.parse(e.anioMes), e.tipo, e.fecha, e.estatus, e.reversaDe, movs);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/seguridad/EntradaNoAutorizada.java": "package com.mx.josesaid.develop.contabilidad.seguridad;\n\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport org.springframework.security.core.AuthenticationException;\nimport org.springframework.security.oauth2.jwt.JwtValidationException;\nimport org.springframework.security.web.AuthenticationEntryPoint;\n\n/**\n * Responde 401 y deja el motivo en WWW-Authenticate. Solo expone el motivo de sesión cerrada;\n * cualquier otro fallo de validación se reporta como \"Invalid token\", sin detalles de decodificación.\n * Spring puede llamar dos veces al punto de entrada en la misma petición: el primer motivo se conserva.\n */\npublic class EntradaNoAutorizada implements AuthenticationEntryPoint {\n\n    private static final String MOTIVO_GENERICO = \"Invalid token\";\n    private static final String ATRIBUTO = EntradaNoAutorizada.class.getName() + \".motivo\";\n\n    /** Responde 401 cuando la petición no trae un token válido o el token fue rechazado. */\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException ex)\n            throws IOException {\n        String previo = (String) request.getAttribute(ATRIBUTO);\n        String motivo = previo != null ? previo : motivo(ex);\n        request.setAttribute(ATRIBUTO, motivo);\n        response.setHeader(\"WWW-Authenticate\",\n                \"Bearer error=\\\"invalid_token\\\", error_description=\\\"\" + motivo + \"\\\"\");\n        response.sendError(HttpServletResponse.SC_UNAUTHORIZED);\n    }\n\n    /** Explica por qué se rechazó el token, en texto breve para el log. */\n    private static String motivo(Throwable ex) {\n        for (Throwable t = ex; t != null; t = t.getCause()) {\n            if (t instanceof JwtValidationException jve && jve.getErrors().stream()\n                    .anyMatch(e -> ValidadorRevocacion.MOTIVO.equals(e.getDescription()))) {\n                return ValidadorRevocacion.MOTIVO;\n            }\n        }\n        return MOTIVO_GENERICO;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/seguridad/ListenerRevocaciones.java": "package com.mx.josesaid.develop.contabilidad.seguridad;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Recibe de usuarios-accesos-ms los cierres de sesión y los aplica a la copia local de revocaciones.\n * Los eventos ajenos se ignoran; un mensaje inválido se registra y se descarta.\n * Cada arranque usa un grupo de consumo nuevo y lee el topic desde el inicio: así reconstruye las\n * revocaciones vigentes. Los eventos vencidos los descarta RevocacionSesiones.\n */\n@Component\npublic class ListenerRevocaciones {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerRevocaciones.class);\n\n    private final RevocacionSesiones revocaciones;\n    private final ObjectMapper mapper;\n\n    /** Recibe la copia local de revocaciones y el lector JSON. */\n    public ListenerRevocaciones(RevocacionSesiones revocaciones, ObjectMapper mapper) {\n        this.revocaciones = revocaciones;\n        this.mapper = mapper;\n    }\n\n    /** Aplica al instante un evento de cierre de sesión recibido por Kafka. */\n    @KafkaListener(topics = \"${seguridad.revocaciones.topico:usuarios-accesos.eventos}\",\n                   groupId = \"contabilidad-ms-revocaciones-#{T(java.util.UUID).randomUUID()}\",\n                   properties = \"auto.offset.reset=earliest\")\n    public void recibir(String mensaje) {\n        try {\n            Sobre sobre = mapper.readValue(mensaje, Sobre.class);\n            String tipo = sobre.tipo();\n            if (!\"sesion-cerrada\".equals(tipo) && !\"sesiones-usuario-cerradas\".equals(tipo)) {\n                return;\n            }\n            Map<String, Object> datos = sobre.datos() == null ? Map.of() : sobre.datos();\n            Instant ocurridoEn = Instant.parse(String.valueOf(datos.get(\"ocurridoEn\")));\n            if (\"sesion-cerrada\".equals(tipo)) {\n                revocaciones.revocarSesion(String.valueOf(datos.get(\"sid\")), ocurridoEn);\n            } else {\n                revocaciones.revocarUsuario(String.valueOf(datos.get(\"usuarioId\")), ocurridoEn);\n            }\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de revocación descartado: {}\", e.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Sobre que publica usuarios-accesos-ms por el outbox.\n     *\n     * @param tipo componente de tipo {@code String}.\n     * @param agregadoId componente de tipo {@code String}.\n     * @param datos componente de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/seguridad/RevocacionSesiones.java": "package com.mx.josesaid.develop.contabilidad.seguridad;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport org.springframework.stereotype.Component;\n\n/**\n * Sesiones cerradas, recordadas en memoria solo mientras pueda haber tokens vigentes.\n * Cada servicio mantiene su copia: un reinicio la vacía, y los tokens revocados expiran igual en 15 minutos.\n */\n@Component\npublic class RevocacionSesiones {\n\n    /** Vida del access token (15 min) más un margen. Pasado ese tiempo, ningún token revocado sigue vigente. */\n    public static final Duration VIDA = Duration.ofMinutes(20);\n\n    private final Map<String, Instant> sesiones = new ConcurrentHashMap<>();\n    private final Map<String, Instant> usuarios = new ConcurrentHashMap<>();\n\n    /** Revoca una sesión (su sid) cerrada en el instante dado. */\n    public void revocarSesion(String sid, Instant ocurridoEn) {\n        if (sid == null || vencido(ocurridoEn)) {\n            return;\n        }\n        sesiones.put(sid, ocurridoEn);\n    }\n\n    /** Revoca los tokens del usuario emitidos antes del instante dado. */\n    public void revocarUsuario(String usuarioId, Instant ocurridoEn) {\n        if (usuarioId == null || vencido(ocurridoEn)) {\n            return;\n        }\n        usuarios.merge(usuarioId, ocurridoEn, (actual, nuevoValor) -> nuevoValor.isAfter(actual) ? nuevoValor : actual);\n    }\n\n    /** true si un token con ese sid, usuario y fecha de emisión ya no debe aceptarse. */\n    public boolean revocado(String sid, String usuarioId, Instant emitidoEn) {\n        limpiar();\n        if (sid != null && sesiones.containsKey(sid)) {\n            return true;\n        }\n        Instant cerradoEn = usuarioId == null ? null : usuarios.get(usuarioId);\n        return cerradoEn != null && emitidoEn != null && emitidoEn.isBefore(cerradoEn);\n    }\n\n    /** Indica si un registro de revocación ya venció y puede descartarse. */\n    private static boolean vencido(Instant ocurridoEn) {\n        return ocurridoEn == null || ocurridoEn.plus(VIDA).isBefore(Instant.now());\n    }\n\n    /** Elimina las revocaciones vencidas para no crecer sin límite. */\n    private void limpiar() {\n        Instant limite = Instant.now().minus(VIDA);\n        sesiones.values().removeIf(t -> t.isBefore(limite));\n        usuarios.values().removeIf(t -> t.isBefore(limite));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/contabilidad/seguridad/ValidadorRevocacion.java": "package com.mx.josesaid.develop.contabilidad.seguridad;\n\nimport org.springframework.security.oauth2.core.OAuth2Error;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\n/** Rechaza los tokens de sesiones cerradas. Se combina con la validación estándar de firma y vencimiento. */\npublic class ValidadorRevocacion implements OAuth2TokenValidator<Jwt> {\n\n    /** Motivo que se devuelve al cliente cuando la sesión fue cerrada. */\n    public static final String MOTIVO = \"La sesion fue cerrada\";\n\n    private static final OAuth2Error REVOCADO = new OAuth2Error(\"invalid_token\", MOTIVO, null);\n\n    private final RevocacionSesiones revocaciones;\n\n    /** Recibe la copia local de revocaciones. */\n    public ValidadorRevocacion(RevocacionSesiones revocaciones) {\n        this.revocaciones = revocaciones;\n    }\n\n    /** Rechaza el JWT si su sesión o su usuario fueron revocados, aunque la firma y el vencimiento sean válidos. */\n    @Override\n    public OAuth2TokenValidatorResult validate(Jwt jwt) {\n        boolean revocado = revocaciones.revocado(jwt.getClaimAsString(\"sid\"), jwt.getSubject(), jwt.getIssuedAt());\n        return revocado ? OAuth2TokenValidatorResult.failure(REVOCADO) : OAuth2TokenValidatorResult.success();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/contabilidad/api/ContabilidadControladorAutorizacionTest.java": "package com.mx.josesaid.develop.contabilidad.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.contabilidad.application.ContabilidadService;\nimport com.mx.josesaid.develop.contabilidad.config.SeguridadConfig;\nimport com.mx.josesaid.develop.contabilidad.infrastructure.idempotencia.Idempotencia;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de ContabilidadControlador.\n * Un rol permitido no debe recibir 401 ni 403; un rol no permitido debe recibir 403.\n * Los cuerpos de las escrituras son válidos: así la validación no oculta la autorización.\n */\n@WebMvcTest(ContabilidadControlador.class)\n@Import({SeguridadConfig.class, ContabilidadControladorAutorizacionTest.Configuracion.class})\nclass ContabilidadControladorAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n    private static final String CUENTA = \"{\\\"codigo\\\":\\\"1101\\\",\\\"nombre\\\":\\\"Caja\\\",\\\"naturaleza\\\":\\\"DEUDORA\\\"}\";\n    private static final String POLIZA = \"{\\\"tipo\\\":\\\"DIARIO\\\",\\\"fecha\\\":\\\"2026-11-05\\\",\\\"movimientos\\\":[\"\n            + \"{\\\"cuentaId\\\":\\\"\" + ID + \"\\\",\\\"cargo\\\":100,\\\"abono\\\":null},\"\n            + \"{\\\"cuentaId\\\":\\\"\" + ID + \"\\\",\\\"cargo\\\":null,\\\"abono\\\":100}]}\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private ContabilidadService servicio;\n\n    @MockitoBean\n    private Idempotencia idempotencia;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    private MockHttpServletRequestBuilder peticion(MockHttpServletRequestBuilder base, String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return base.with(jwt().jwt(j -> j.subject(SUJETO)).authorities(autoridades));\n    }\n\n    private MockHttpServletRequestBuilder lectura(String ruta, String rol) {\n        return peticion(get(ruta), rol);\n    }\n\n    private MockHttpServletRequestBuilder escritura(String ruta, String cuerpo, String rol) {\n        var base = post(ruta).contentType(MediaType.APPLICATION_JSON);\n        if (cuerpo != null) {\n            base = base.content(cuerpo);\n        }\n        return peticion(base, rol);\n    }\n\n    private void permitido(MockHttpServletRequestBuilder req, String descripcion, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(req).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        org.assertj.core.api.Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", descripcion, rol)\n                .isNotIn(401, 403);\n    }\n\n    private void denegado(MockHttpServletRequestBuilder req) throws Exception {\n        mvc.perform(req).andExpect(status().isForbidden());\n    }\n\n    @Test\n    void listarCuentas() throws Exception {\n        permitido(lectura(\"/v1/cuentas\", \"CONTADOR\"), \"GET /v1/cuentas\", \"CONTADOR\");\n        permitido(lectura(\"/v1/cuentas\", \"DIRECCION\"), \"GET /v1/cuentas\", \"DIRECCION\");\n        denegado(lectura(\"/v1/cuentas\", \"VENTAS\"));\n    }\n\n    @Test\n    void crearCuenta() throws Exception {\n        permitido(escritura(\"/v1/cuentas\", CUENTA, \"CONTADOR\"), \"POST /v1/cuentas\", \"CONTADOR\");\n        denegado(escritura(\"/v1/cuentas\", CUENTA, \"DIRECCION\"));\n        denegado(escritura(\"/v1/cuentas\", CUENTA, \"VENTAS\"));\n    }\n\n    @Test\n    void listarPolizas() throws Exception {\n        String ruta = \"/v1/polizas?periodo=2026-11\";\n        permitido(lectura(ruta, \"CONTADOR\"), \"GET /v1/polizas\", \"CONTADOR\");\n        permitido(lectura(ruta, \"DIRECCION\"), \"GET /v1/polizas\", \"DIRECCION\");\n        denegado(lectura(ruta, \"VENTAS\"));\n    }\n\n    @Test\n    void obtenerPoliza() throws Exception {\n        String ruta = \"/v1/polizas/\" + ID;\n        permitido(lectura(ruta, \"CONTADOR\"), \"GET /v1/polizas/{id}\", \"CONTADOR\");\n        permitido(lectura(ruta, \"DIRECCION\"), \"GET /v1/polizas/{id}\", \"DIRECCION\");\n        denegado(lectura(ruta, \"VENTAS\"));\n    }\n\n    @Test\n    void registrarPoliza() throws Exception {\n        permitido(escritura(\"/v1/polizas\", POLIZA, \"CONTADOR\"), \"POST /v1/polizas\", \"CONTADOR\");\n        denegado(escritura(\"/v1/polizas\", POLIZA, \"DIRECCION\"));\n        denegado(escritura(\"/v1/polizas\", POLIZA, \"VENTAS\"));\n    }\n\n    @Test\n    void reversarPoliza() throws Exception {\n        String ruta = \"/v1/polizas/\" + ID + \"/reversa\";\n        permitido(escritura(ruta, null, \"CONTADOR\"), \"POST reversa\", \"CONTADOR\");\n        denegado(escritura(ruta, null, \"DIRECCION\"));\n    }\n\n    @Test\n    void cerrarPeriodo() throws Exception {\n        String ruta = \"/v1/periodos/2026-11/cierre\";\n        permitido(escritura(ruta, null, \"CONTADOR\"), \"POST cierre\", \"CONTADOR\");\n        denegado(escritura(ruta, null, \"DIRECCION\"));\n    }\n\n    @Test\n    void estadosFinancieros() throws Exception {\n        String ruta = \"/v1/estados-financieros?periodo=2026-11\";\n        permitido(lectura(ruta, \"CONTADOR\"), \"GET estados-financieros\", \"CONTADOR\");\n        permitido(lectura(ruta, \"DIRECCION\"), \"GET estados-financieros\", \"DIRECCION\");\n        denegado(lectura(ruta, \"VENTAS\"));\n    }\n\n    @Test\n    void sinRolNoHayAcceso() throws Exception {\n        denegado(lectura(\"/v1/cuentas\", \"\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/contabilidad/api/ContabilidadControladorValidacionTest.java": "package com.mx.josesaid.develop.contabilidad.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.contabilidad.application.ContabilidadService;\nimport com.mx.josesaid.develop.contabilidad.infrastructure.idempotencia.Idempotencia;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\n\n@WebMvcTest(ContabilidadControlador.class)\n@Import(ContabilidadControladorValidacionTest.Configuracion.class)\nclass ContabilidadControladorValidacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private ContabilidadService servicio;\n\n    @MockitoBean\n    private Idempotencia idempotencia;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    @Test\n    void parametroDemasiadoLargoDa400() throws Exception {\n        mvc.perform(get(\"/v1/polizas\").param(\"periodo\", \"A\".repeat(21))\n                        .with(jwt().jwt(j -> j.subject(SUJETO))\n                                .authorities(new SimpleGrantedAuthority(\"ROLE_CONTADOR\"))))\n                .andExpect(status().isBadRequest());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/contabilidad/api/ContabilidadIT.java": "package com.mx.josesaid.develop.contabilidad.api;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.jayway.jsonpath.JsonPath;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.MvcResult;\nimport org.springframework.test.web.servlet.request.RequestPostProcessor;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = \"contabilidad.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\")\n@AutoConfigureMockMvc\n@Testcontainers\nclass ContabilidadIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private MockMvc mvc;\n\n    @Test\n    void listaLasPolizasDelPeriodo() throws Exception {\n        String caja = crearCuenta(\"1102\", \"Bancos\", \"DEUDORA\");\n        String ventas = crearCuenta(\"4102\", \"Ingresos\", \"ACREEDORA\");\n        mvc.perform(post(\"/v1/polizas\").with(rol(\"CONTADOR\"))\n                        .contentType(\"application/json\")\n                        .content(poliza(caja, ventas, \"250\", \"250\")))\n                .andExpect(status().isCreated());\n\n        mvc.perform(get(\"/v1/polizas?periodo=2026-10\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$[0].periodo\").value(\"2026-10\"));\n\n        mvc.perform(get(\"/v1/polizas?periodo=2026-10\").with(rol(\"VENTAS\")))\n                .andExpect(status().isForbidden());\n    }\n\n    @Test\n    void flujoContableConRolesYCierre() throws Exception {\n        mvc.perform(get(\"/v1/estados-financieros?periodo=2026-10\"))\n                .andExpect(status().isUnauthorized());\n\n        // DIRECCION no escribe\n        mvc.perform(post(\"/v1/cuentas\").with(rol(\"DIRECCION\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"codigo\\\":\\\"1101\\\",\\\"nombre\\\":\\\"Caja\\\",\\\"naturaleza\\\":\\\"DEUDORA\\\"}\"))\n                .andExpect(status().isForbidden());\n\n        String caja = crearCuenta(\"1101\", \"Caja\", \"DEUDORA\");\n        String ventas = crearCuenta(\"4101\", \"Ventas\", \"ACREEDORA\");\n\n        // Póliza descuadrada: 422\n        mvc.perform(post(\"/v1/polizas\").with(rol(\"CONTADOR\"))\n                        .contentType(\"application/json\")\n                        .content(poliza(caja, ventas, \"100\", \"90\")))\n                .andExpect(status().isUnprocessableEntity());\n\n        // Póliza cuadrada: 201\n        MvcResult ok = mvc.perform(post(\"/v1/polizas\").with(rol(\"CONTADOR\"))\n                        .contentType(\"application/json\")\n                        .content(poliza(caja, ventas, \"100\", \"100\")))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.periodo\").value(\"2026-10\"))\n                .andReturn();\n        String polizaId = JsonPath.read(ok.getResponse().getContentAsString(), \"$.id\");\n\n        // Cierre y bloqueo de movimientos\n        mvc.perform(post(\"/v1/periodos/2026-10/cierre\").with(rol(\"CONTADOR\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"CERRADO\"));\n        mvc.perform(post(\"/v1/polizas\").with(rol(\"CONTADOR\"))\n                        .contentType(\"application/json\")\n                        .content(poliza(caja, ventas, \"10\", \"10\")))\n                .andExpect(status().isConflict());\n\n        // Consulta de estados financieros por DIRECCION\n        mvc.perform(get(\"/v1/estados-financieros?periodo=2026-10\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.cuadra\").value(true));\n\n        mvc.perform(get(\"/v1/polizas/\" + polizaId).with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"APLICADA\"));\n    }\n\n    private String crearCuenta(String codigo, String nombre, String naturaleza) throws Exception {\n        MvcResult r = mvc.perform(post(\"/v1/cuentas\").with(rol(\"CONTADOR\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"codigo\\\":\\\"\" + codigo + \"\\\",\\\"nombre\\\":\\\"\" + nombre + \"\\\",\\\"naturaleza\\\":\\\"\" + naturaleza + \"\\\"}\"))\n                .andExpect(status().isCreated())\n                .andReturn();\n        return JsonPath.read(r.getResponse().getContentAsString(), \"$.id\");\n    }\n\n    private static String poliza(String cuentaCargo, String cuentaAbono, String cargo, String abono) {\n        return \"{\\\"tipo\\\":\\\"INGRESO\\\",\\\"fecha\\\":\\\"2026-10-15\\\",\\\"movimientos\\\":[\"\n                + \"{\\\"cuentaId\\\":\\\"\" + cuentaCargo + \"\\\",\\\"cargo\\\":\" + cargo + \"},\"\n                + \"{\\\"cuentaId\\\":\\\"\" + cuentaAbono + \"\\\",\\\"abono\\\":\" + abono + \"}]}\";\n    }\n\n    private static RequestPostProcessor rol(String rol) {\n        return jwt().authorities(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n    }\n\n    @Test\n    void mismaIdempotencyKeyNoDuplicaLaPoliza() throws Exception {\n        int sufijo = new java.util.Random().nextInt(900) + 100;\n        String caja = crearCuenta(\"1201-\" + sufijo, \"Caja replay\", \"DEUDORA\");\n        String ventas = crearCuenta(\"4201-\" + sufijo, \"Ventas replay\", \"ACREEDORA\");\n        String cuerpo = \"{\\\"tipo\\\":\\\"DIARIO\\\",\\\"fecha\\\":\\\"2026-09-15\\\",\\\"movimientos\\\":[\"\n                + \"{\\\"cuentaId\\\":\\\"\" + caja + \"\\\",\\\"cargo\\\":50},\"\n                + \"{\\\"cuentaId\\\":\\\"\" + ventas + \"\\\",\\\"abono\\\":50}]}\";\n        String clave = \"prueba-\" + java.util.UUID.randomUUID();\n        MvcResult primero = mvc.perform(post(\"/v1/polizas\").with(rol(\"CONTADOR\")).header(\"Idempotency-Key\", clave)\n                        .contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        MvcResult reintento = mvc.perform(post(\"/v1/polizas\").with(rol(\"CONTADOR\")).header(\"Idempotency-Key\", clave)\n                        .contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        assertEquals((String) JsonPath.read(primero.getResponse().getContentAsString(), \"$.id\"),\n                (String) JsonPath.read(reintento.getResponse().getContentAsString(), \"$.id\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/contabilidad/application/ContabilidadServiceTest.java": "package com.mx.josesaid.develop.contabilidad.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport com.mx.josesaid.develop.contabilidad.domain.ConflictoException;\nimport com.mx.josesaid.develop.contabilidad.domain.CuentaContable;\nimport com.mx.josesaid.develop.contabilidad.domain.CuentaRepositorio;\nimport com.mx.josesaid.develop.contabilidad.domain.Movimiento;\nimport com.mx.josesaid.develop.contabilidad.domain.Naturaleza;\nimport com.mx.josesaid.develop.contabilidad.domain.Periodo;\nimport com.mx.josesaid.develop.contabilidad.domain.PeriodoRepositorio;\nimport com.mx.josesaid.develop.contabilidad.domain.Poliza;\nimport com.mx.josesaid.develop.contabilidad.domain.PolizaRepositorio;\nimport com.mx.josesaid.develop.contabilidad.domain.ReglaDeNegocioException;\nimport com.mx.josesaid.develop.contabilidad.domain.TipoPoliza;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass ContabilidadServiceTest {\n\n    private final Map<UUID, CuentaContable> cuentas = new HashMap<>();\n    private final Map<YearMonth, Periodo> periodos = new HashMap<>();\n    private final Map<UUID, Poliza> polizas = new HashMap<>();\n    private final List<EventoDominio> eventos = new ArrayList<>();\n    private ContabilidadService servicio;\n\n    @BeforeEach\n    void preparar() {\n        CuentaRepositorio cuentaRepo = new CuentaRepositorio() {\n            public CuentaContable guardar(CuentaContable c) { cuentas.put(c.getId(), c); return c; }\n            public Optional<CuentaContable> buscarPorId(UUID id) { return Optional.ofNullable(cuentas.get(id)); }\n            public boolean existePorCodigo(String codigo) {\n                return cuentas.values().stream().anyMatch(c -> c.getCodigo().equals(codigo));\n            }\n            public List<CuentaContable> listarActivas() {\n                return cuentas.values().stream().filter(CuentaContable::isActiva)\n                        .sorted(java.util.Comparator.comparing(CuentaContable::getCodigo)).toList();\n            }\n        };\n        PeriodoRepositorio periodoRepo = new PeriodoRepositorio() {\n            public Periodo guardar(Periodo p) { periodos.put(p.getAnioMes(), p); return p; }\n            public Optional<Periodo> buscarPorAnioMes(YearMonth ym) { return Optional.ofNullable(periodos.get(ym)); }\n        };\n        PolizaRepositorio polizaRepo = new PolizaRepositorio() {\n            public Poliza guardar(Poliza p) { polizas.put(p.getId(), p); return p; }\n            public Optional<Poliza> buscarPorId(UUID id) { return Optional.ofNullable(polizas.get(id)); }\n            public List<Poliza> buscarPorPeriodo(YearMonth ym) {\n                return polizas.values().stream().filter(p -> p.getPeriodo().equals(ym)).toList();\n            }\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-10-20T10:00:00Z\"), ZoneOffset.UTC);\n        servicio = new ContabilidadService(cuentaRepo, periodoRepo, polizaRepo, eventos::add, reloj);\n    }\n\n    @Test\n    void noSePermitenCodigosDeCuentaDuplicados() {\n        servicio.crearCuenta(\"1101\", \"Caja\", Naturaleza.DEUDORA);\n        assertThatThrownBy(() -> servicio.crearCuenta(\"1101\", \"Otra\", Naturaleza.DEUDORA))\n                .isInstanceOf(ConflictoException.class);\n    }\n\n    @Test\n    void polizaDescuadradaNoSeGuardaNiPublicaEvento() {\n        UUID caja = servicio.crearCuenta(\"1101\", \"Caja\", Naturaleza.DEUDORA).getId();\n        UUID ventas = servicio.crearCuenta(\"4101\", \"Ventas\", Naturaleza.ACREEDORA).getId();\n        List<Movimiento> mal = List.of(\n                new Movimiento(caja, new BigDecimal(\"100\"), null),\n                new Movimiento(ventas, null, new BigDecimal(\"50\")));\n\n        assertThatThrownBy(() -> servicio.registrarPoliza(TipoPoliza.INGRESO, LocalDate.of(2026, 10, 1), mal))\n                .isInstanceOf(ReglaDeNegocioException.class);\n        assertThat(polizas).isEmpty();\n        assertThat(eventos).isEmpty();\n    }\n\n    @Test\n    void periodoCerradoRechazaPolizasYCierreEmiteEvento() {\n        UUID caja = servicio.crearCuenta(\"1101\", \"Caja\", Naturaleza.DEUDORA).getId();\n        UUID ventas = servicio.crearCuenta(\"4101\", \"Ventas\", Naturaleza.ACREEDORA).getId();\n        List<Movimiento> ok = List.of(\n                new Movimiento(caja, new BigDecimal(\"100\"), null),\n                new Movimiento(ventas, null, new BigDecimal(\"100\")));\n        servicio.registrarPoliza(TipoPoliza.INGRESO, LocalDate.of(2026, 10, 1), ok);\n        assertThat(eventos).extracting(EventoDominio::tipo).containsExactly(ContabilidadService.EVENTO_POLIZA_APLICADA);\n\n        servicio.cerrarPeriodo(YearMonth.of(2026, 10));\n        assertThat(eventos).extracting(EventoDominio::tipo).contains(ContabilidadService.EVENTO_PERIODO_CERRADO);\n        assertThatThrownBy(() -> servicio.registrarPoliza(TipoPoliza.INGRESO, LocalDate.of(2026, 10, 2), ok))\n                .isInstanceOf(ConflictoException.class);\n    }\n\n    @Test\n    void balanzaDelPeriodoCuadra() {\n        UUID caja = servicio.crearCuenta(\"1101\", \"Caja\", Naturaleza.DEUDORA).getId();\n        UUID ventas = servicio.crearCuenta(\"4101\", \"Ventas\", Naturaleza.ACREEDORA).getId();\n        servicio.registrarPoliza(TipoPoliza.INGRESO, LocalDate.of(2026, 10, 1), List.of(\n                new Movimiento(caja, new BigDecimal(\"250\"), null),\n                new Movimiento(ventas, null, new BigDecimal(\"250\"))));\n\n        assertThat(servicio.estadosFinancieros(YearMonth.of(2026, 10)).cuadra()).isTrue();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/contabilidad/config/RelojConfigTest.java": "package com.mx.josesaid.develop.contabilidad.config;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport java.time.ZoneId;\nimport org.junit.jupiter.api.Test;\n\nclass RelojConfigTest {\n\n    @Test\n    void relojUsaLaZonaDeOperacion() {\n        assertEquals(ZoneId.of(\"America/Mexico_City\"), new RelojConfig().reloj().getZone());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/contabilidad/domain/PolizaTest.java": "package com.mx.josesaid.develop.contabilidad.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.util.List;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass PolizaTest {\n\n    private static final UUID CAJA = UUID.randomUUID();\n    private static final UUID VENTAS = UUID.randomUUID();\n    private static final LocalDate FECHA = LocalDate.of(2026, 10, 15);\n\n    private static List<Movimiento> cuadrada() {\n        return List.of(\n                new Movimiento(CAJA, new BigDecimal(\"100\"), null),\n                new Movimiento(VENTAS, null, new BigDecimal(\"100\")));\n    }\n\n    @Test\n    void polizaCuadradaSeAplicaEnSuPeriodo() {\n        Poliza p = Poliza.aplicar(TipoPoliza.INGRESO, FECHA, cuadrada());\n        assertThat(p.getEstatus()).isEqualTo(EstatusPoliza.APLICADA);\n        assertThat(p.getPeriodo()).isEqualTo(YearMonth.of(2026, 10));\n        assertThat(p.total()).isEqualByComparingTo(\"100.00\");\n    }\n\n    @Test\n    void polizaDescuadradaSeRechazaConMensaje() {\n        List<Movimiento> mal = List.of(\n                new Movimiento(CAJA, new BigDecimal(\"100\"), null),\n                new Movimiento(VENTAS, null, new BigDecimal(\"90\")));\n        assertThatThrownBy(() -> Poliza.aplicar(TipoPoliza.DIARIO, FECHA, mal))\n                .isInstanceOf(ReglaDeNegocioException.class)\n                .hasMessageContaining(\"no cuadra\");\n    }\n\n    @Test\n    void movimientoConCargoYAbonoEsInvalido() {\n        assertThatThrownBy(() -> new Movimiento(CAJA, BigDecimal.ONE, BigDecimal.ONE))\n                .isInstanceOf(ReglaDeNegocioException.class);\n        assertThatThrownBy(() -> new Movimiento(CAJA, null, null))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n\n    @Test\n    void reversaInvierteMovimientosYMarcaLaOriginal() {\n        Poliza original = Poliza.aplicar(TipoPoliza.INGRESO, FECHA, cuadrada());\n        Poliza reversa = original.reversar(LocalDate.of(2026, 10, 20));\n\n        assertThat(original.getEstatus()).isEqualTo(EstatusPoliza.REVERSADA);\n        assertThat(reversa.getReversaDe()).isEqualTo(original.getId());\n        assertThat(reversa.getMovimientos().get(0).getAbono()).isEqualByComparingTo(\"100.00\");\n        assertThat(reversa.getMovimientos().get(0).getCargo()).isEqualByComparingTo(\"0.00\");\n        assertThatThrownBy(() -> original.reversar(LocalDate.of(2026, 10, 21)))\n                .isInstanceOf(ConflictoException.class);\n    }\n\n    @Test\n    void periodoCerradoNoSeCierraDosVeces() {\n        Periodo p = Periodo.abrir(YearMonth.of(2026, 10));\n        p.cerrar();\n        assertThat(p.estaCerrado()).isTrue();\n        assertThatThrownBy(p::cerrar).isInstanceOf(ConflictoException.class);\n    }\n\n    @Test\n    void balanzaCalculaSaldoSegunNaturalezaYCuadra() {\n        CuentaContable caja = CuentaContable.reconstruir(CAJA, \"1101\", \"Caja\", Naturaleza.DEUDORA, true);\n        CuentaContable ventas = CuentaContable.reconstruir(VENTAS, \"4101\", \"Ventas\", Naturaleza.ACREEDORA, true);\n        Poliza p = Poliza.aplicar(TipoPoliza.INGRESO, FECHA, cuadrada());\n\n        Balanza b = Balanza.calcular(YearMonth.of(2026, 10), List.of(p),\n                java.util.Map.of(CAJA, caja, VENTAS, ventas));\n\n        assertThat(b.cuadra()).isTrue();\n        assertThat(b.totalCargos()).isEqualByComparingTo(b.totalAbonos());\n        Balanza.Linea lineaVentas = b.lineas().stream().filter(l -> l.codigo().equals(\"4101\")).findFirst().orElseThrow();\n        assertThat(lineaVentas.saldo()).isEqualByComparingTo(\"100.00\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/contabilidad/infrastructure/idempotencia/RegistroIdempotenciaIT.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.idempotencia;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport org.flywaydb.core.Flyway;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.jdbc.datasource.DriverManagerDataSource;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Reserva de Idempotency-Key contra PostgreSQL real (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@Testcontainers\nclass RegistroIdempotenciaIT {\n\n    @Container\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    private static final Instant T0 = Instant.parse(\"2026-11-05T12:00:00Z\");\n\n    private JdbcTemplate jdbc;\n\n    @BeforeEach\n    void migrarBaseLimpia() {\n        DriverManagerDataSource ds = new DriverManagerDataSource(\n                postgres.getJdbcUrl(), postgres.getUsername(), postgres.getPassword());\n        Flyway flyway = Flyway.configure().dataSource(ds).cleanDisabled(false).load();\n        flyway.clean();\n        flyway.migrate();\n        jdbc = new JdbcTemplate(ds);\n    }\n\n    private RegistroIdempotencia registroEn(Instant instante) {\n        return new RegistroIdempotencia(jdbc, Clock.fixed(instante, ZoneOffset.UTC));\n    }\n\n    @Test\n    void reservaFrescaNoSeRetoma() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        assertFalse(registroEn(T0.plusSeconds(60)).reservar(\"k1\", \"h1\"));\n    }\n\n    @Test\n    void reservaSinCompletarSeRetomaTrasLaConcesion() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        assertTrue(registroEn(T0.plusSeconds(180)).reservar(\"k1\", \"h2\"));\n        assertEquals(\"h2\", registroEn(T0.plusSeconds(180)).buscar(\"k1\").orElseThrow().huella());\n        assertFalse(registroEn(T0.plusSeconds(200)).reservar(\"k1\", \"h2\"));\n    }\n\n    @Test\n    void respuestaCompletadaNoSeRetomaAunquePaseLaConcesion() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        registroEn(T0).completar(\"k1\", 201, \"{}\");\n        assertFalse(registroEn(T0.plusSeconds(180)).reservar(\"k1\", \"h1\"));\n        assertTrue(registroEn(T0.plusSeconds(180)).buscar(\"k1\").orElseThrow().completada());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/contabilidad/infrastructure/indicadores/PublicadorIndicadoresPolizasIT.java": "package com.mx.josesaid.develop.contabilidad.infrastructure.indicadores;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport com.jayway.jsonpath.JsonPath;\nimport java.time.Duration;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.Collections;\nimport java.util.Properties;\nimport java.util.UUID;\nimport org.apache.kafka.clients.consumer.ConsumerConfig;\nimport org.apache.kafka.clients.consumer.KafkaConsumer;\nimport org.apache.kafka.common.serialization.StringDeserializer;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = \"contabilidad.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\")\n@Testcontainers\nclass PublicadorIndicadoresPolizasIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private JdbcTemplate jdbc;\n\n    @Autowired\n    private PublicadorIndicadoresPolizas publicador;\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    @Test\n    void polizasDelMesCuentaSoloLasAplicadas() {\n        String periodo = YearMonth.now(ZONA).toString();\n        jdbc.update(\"INSERT INTO periodos (anio_mes, estatus, version) VALUES (?, 'ABIERTO', 0)\", periodo);\n        poliza(periodo, \"APLICADA\");\n        poliza(periodo, \"APLICADA\");\n        poliza(periodo, \"BORRADOR\");  // excluida: no aplicada\n\n        publicador.publicarPeriodo(periodo);\n\n        String clave = PublicadorIndicadoresPolizas.AREA + \"|\" + PublicadorIndicadoresPolizas.NOMBRE + \"|\" + periodo;\n        String payload = leerIndicador(clave);\n        assertEquals(\"FINANZAS_CONTABILIDAD\", JsonPath.read(payload, \"$.area\"));\n        assertEquals(2.0, ((Number) JsonPath.read(payload, \"$.valor\")).doubleValue(), 0.001);\n    }\n\n    private void poliza(String periodo, String estatus) {\n        jdbc.update(\"\"\"\n                INSERT INTO polizas (id, anio_mes, tipo, fecha, estatus, version)\n                VALUES (?, ?, 'DIARIO', ?, ?, 0)\n                \"\"\", UUID.randomUUID(), periodo, java.sql.Date.valueOf(LocalDate.now(ZONA)), estatus);\n    }\n\n    private String leerIndicador(String clave) {\n        try (KafkaConsumer<String, String> consumidor = new KafkaConsumer<>(propiedades())) {\n            consumidor.subscribe(Collections.singletonList(\"indicadores-areas\"));\n            long limite = System.currentTimeMillis() + 30_000;\n            while (System.currentTimeMillis() < limite) {\n                for (var registro : consumidor.poll(Duration.ofMillis(500))) {\n                    if (clave.equals(registro.key())) {\n                        return registro.value();\n                    }\n                }\n            }\n            throw new AssertionError(\"No llegó el indicador \" + clave);\n        }\n    }\n\n    private Properties propiedades() {\n        Properties p = new Properties();\n        p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());\n        p.put(ConsumerConfig.GROUP_ID_CONFIG, \"test-\" + UUID.randomUUID());\n        p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, \"earliest\");\n        p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        return p;\n    }\n}\n"};
